window.STUDY_DATA={"9":{"title":"Kinematics","chapter":2,"mcqs":[{"id":"9th-ch2-001","number":1,"prompt":"A passenger sitting in a moving bus is at rest relative to which object?","options":["The bus seat","A roadside tree","A lamp post","A stationary shop"],"correct":0,"answer":"The bus seat","solution":"The passenger and seat keep the same relative position, although both move relative to the road.","difficulty":"Easy","topic":"Reference frames","printed_pages":"32","explanation":"The passenger and seat keep the same relative position, although both move relative to the road."},{"id":"9th-ch2-002","number":2,"prompt":"Which statement best describes motion?","options":["An object must change its shape","An object must change its mass","An object must move in a circle","Position changes relative to a reference point with time"],"correct":3,"answer":"Position changes relative to a reference point with time","solution":"Motion is a change of position with time relative to a chosen reference point.","difficulty":"Easy","topic":"Reference frames","printed_pages":"32","explanation":"Motion is a change of position with time relative to a chosen reference point."},{"id":"9th-ch2-003","number":3,"prompt":"A train travels along a straight track. Its motion is mainly which type?","options":["Rotatory motion","Vibratory motion","Linear motion","Random motion"],"correct":2,"answer":"Linear motion","solution":"Translation along a straight path is linear motion.","difficulty":"Easy","topic":"Types of motion","printed_pages":"33–34","explanation":"Translation along a straight path is linear motion."},{"id":"9th-ch2-004","number":4,"prompt":"A stone moves around a circle at the end of a string. Its motion around the hand is which type?","options":["Vibratory motion","Circular motion","Linear motion","Random motion"],"correct":1,"answer":"Circular motion","solution":"The stone follows a circular path around a fixed centre.","difficulty":"Easy","topic":"Types of motion","printed_pages":"34","explanation":"The stone follows a circular path around a fixed centre."},{"id":"9th-ch2-005","number":5,"prompt":"The irregular movement of a butterfly is an example of which motion?","options":["Rotatory motion","Uniform linear motion","Uniform circular motion","Random motion"],"correct":3,"answer":"Random motion","solution":"An irregular path with unpredictable changes of direction is random motion.","difficulty":"Easy","topic":"Types of motion","printed_pages":"35","explanation":"An irregular path with unpredictable changes of direction is random motion."},{"id":"9th-ch2-006","number":6,"prompt":"The spinning of a ceiling fan about its fixed axis is which motion?","options":["Linear motion","Translatory motion only","Rotatory motion","Random motion"],"correct":2,"answer":"Rotatory motion","solution":"A body turning about its own fixed axis has rotatory motion.","difficulty":"Easy","topic":"Types of motion","printed_pages":"35","explanation":"A body turning about its own fixed axis has rotatory motion."},{"id":"9th-ch2-007","number":7,"prompt":"The repeated to-and-fro movement of a pendulum is which motion?","options":["Vibratory motion","Linear motion in one direction","Rotatory motion about its own axis","Random motion"],"correct":0,"answer":"Vibratory motion","solution":"A pendulum moves back and forth about its mean position, so its motion is vibratory.","difficulty":"Easy","topic":"Types of motion","printed_pages":"36","explanation":"A pendulum moves back and forth about its mean position, so its motion is vibratory."},{"id":"9th-ch2-008","number":8,"prompt":"Which quantity describes the total length of a path travelled?","options":["Distance","Velocity","Displacement","Acceleration"],"correct":0,"answer":"Distance","solution":"Distance measures the complete path length, irrespective of direction.","difficulty":"Easy","topic":"Distance and displacement","printed_pages":"37","explanation":"Distance measures the complete path length, irrespective of direction."},{"id":"9th-ch2-009","number":9,"prompt":"Which quantity includes both magnitude and direction?","options":["Time","Displacement","Distance","Speed"],"correct":1,"answer":"Displacement","solution":"Displacement is a vector from the initial position to the final position.","difficulty":"Easy","topic":"Scalars and vectors","printed_pages":"37, 44","explanation":"Displacement is a vector from the initial position to the final position."},{"id":"9th-ch2-010","number":10,"prompt":"A student walks 30 m east and then 10 m west. What is the total distance travelled?","options":["10 m","20 m","40 m","30 m"],"correct":2,"answer":"40 m","solution":"Distance adds both path lengths: 30 + 10 = 40 m.","difficulty":"Easy","topic":"Distance and displacement","printed_pages":"37","explanation":"Distance adds both path lengths: 30 + 10 = 40 m."},{"id":"9th-ch2-011","number":11,"prompt":"A runner completes one full lap of a circular track and returns to the starting point. What is the displacement?","options":["0 m","One circumference","One radius","One diameter"],"correct":0,"answer":"0 m","solution":"Initial and final positions coincide, so displacement is zero even though distance is nonzero.","difficulty":"Easy","topic":"Distance and displacement","printed_pages":"37","explanation":"Initial and final positions coincide, so displacement is zero even though distance is nonzero."},{"id":"9th-ch2-012","number":12,"prompt":"Which pair contains only scalar quantities?","options":["Speed and time","Velocity and time","Displacement and speed","Acceleration and velocity"],"correct":0,"answer":"Speed and time","solution":"Speed and time need magnitude only; velocity, displacement and acceleration also have direction.","difficulty":"Easy","topic":"Scalars and vectors","printed_pages":"44","explanation":"Speed and time need magnitude only; velocity, displacement and acceleration also have direction."},{"id":"9th-ch2-013","number":13,"prompt":"In an arrow used to represent a vector, what does the arrowhead show?","options":["Mass","Time","Direction","Temperature"],"correct":2,"answer":"Direction","solution":"The arrowhead indicates vector direction; a chosen length scale represents magnitude.","difficulty":"Easy","topic":"Vector representation","printed_pages":"44–45","explanation":"The arrowhead indicates vector direction; a chosen length scale represents magnitude."},{"id":"9th-ch2-014","number":14,"prompt":"What is the SI unit of speed?","options":["s","m/s","m/s²","m"],"correct":1,"answer":"m/s","solution":"Speed is distance divided by time, so its SI unit is metre per second.","difficulty":"Easy","topic":"Speed and velocity","printed_pages":"38","explanation":"Speed is distance divided by time, so its SI unit is metre per second."},{"id":"9th-ch2-015","number":15,"prompt":"A cyclist travels 120 m in 20 s. What is the average speed?","options":["12 m/s","6 m/s","4 m/s","24 m/s"],"correct":1,"answer":"6 m/s","solution":"Average speed = total distance / total time = 120 / 20 = 6 m/s.","difficulty":"Easy","topic":"Speed and velocity","printed_pages":"38","explanation":"Average speed = total distance / total time = 120 / 20 = 6 m/s."},{"id":"9th-ch2-016","number":16,"prompt":"Which relation defines average velocity?","options":["Speed divided by time interval","Acceleration multiplied by distance","Distance multiplied by time interval","Displacement divided by time interval"],"correct":3,"answer":"Displacement divided by time interval","solution":"Average velocity uses displacement, whereas average speed uses total distance.","difficulty":"Easy","topic":"Speed and velocity","printed_pages":"39","explanation":"Average velocity uses displacement, whereas average speed uses total distance."},{"id":"9th-ch2-017","number":17,"prompt":"An object moves equal distances in equal time intervals. Its speed is described as what?","options":["Increasing speed","Decreasing speed","Uniform speed","Zero speed"],"correct":2,"answer":"Uniform speed","solution":"Uniform speed means that the distance covered per unit time remains constant.","difficulty":"Easy","topic":"Speed and velocity","printed_pages":"39","explanation":"Uniform speed means that the distance covered per unit time remains constant."},{"id":"9th-ch2-018","number":18,"prompt":"What is the SI unit of acceleration?","options":["s/m","m/s²","m/s","m²/s"],"correct":1,"answer":"m/s²","solution":"Acceleration is change in velocity divided by time: (m/s) / s = m/s².","difficulty":"Easy","topic":"Acceleration","printed_pages":"41","explanation":"Acceleration is change in velocity divided by time: (m/s) / s = m/s²."},{"id":"9th-ch2-019","number":19,"prompt":"Velocity increases from 4 m/s to 10 m/s in 3 s. What is the average acceleration?","options":["3 m/s²","2 m/s²","6 m/s²","14 m/s²"],"correct":1,"answer":"2 m/s²","solution":"a = (v − u) / t = (10 − 4) / 3 = 2 m/s².","difficulty":"Easy","topic":"Acceleration","printed_pages":"41–42","explanation":"a = (v − u) / t = (10 − 4) / 3 = 2 m/s²."},{"id":"9th-ch2-020","number":20,"prompt":"An object moves with constant velocity. What is its acceleration?","options":["Positive and increasing","Zero","Equal to its speed","Negative and constant"],"correct":1,"answer":"Zero","solution":"There is no change in either magnitude or direction of velocity, so acceleration is zero.","difficulty":"Easy","topic":"Acceleration","printed_pages":"41–42","explanation":"There is no change in either magnitude or direction of velocity, so acceleration is zero."},{"id":"9th-ch2-021","number":21,"prompt":"What does the gradient of a distance–time graph represent?","options":["Time","Mass","Acceleration","Speed"],"correct":3,"answer":"Speed","solution":"Gradient = change in distance / change in time, which gives speed.","difficulty":"Easy","topic":"Motion graphs","printed_pages":"45–46","explanation":"Gradient = change in distance / change in time, which gives speed."},{"id":"9th-ch2-022","number":22,"prompt":"A horizontal line on a distance–time graph indicates what?","options":["The object has increasing speed","The object is at rest","The object has constant nonzero acceleration","The object has decreasing mass"],"correct":1,"answer":"The object is at rest","solution":"Distance is unchanged while time passes, so the object is at rest.","difficulty":"Easy","topic":"Motion graphs","printed_pages":"46","explanation":"Distance is unchanged while time passes, so the object is at rest."},{"id":"9th-ch2-023","number":23,"prompt":"Which equation links initial velocity u, final velocity v, acceleration a and time t for constant acceleration?","options":["v = u + a/t","v = u − at²","v = ut + a","v = u + at"],"correct":3,"answer":"v = u + at","solution":"For constant acceleration, a = (v − u) / t rearranges to v = u + at.","difficulty":"Easy","topic":"Equations of motion","printed_pages":"47–48","explanation":"For constant acceleration, a = (v − u) / t rearranges to v = u + at."},{"id":"9th-ch2-024","number":24,"prompt":"What does free fall mean?","options":["Motion caused only by air resistance","Motion under gravity alone","Any motion at constant speed","Motion with no gravity"],"correct":1,"answer":"Motion under gravity alone","solution":"A freely falling body is acted on only by gravity; air resistance is neglected.","difficulty":"Easy","topic":"Free fall","printed_pages":"50–51","explanation":"A freely falling body is acted on only by gravity; air resistance is neglected."},{"id":"9th-ch2-025","number":25,"prompt":"A body is released from rest. What is its initial velocity?","options":["0 m/s","9.8 m/s²","10 m/s downward","10 m/s upward"],"correct":0,"answer":"0 m/s","solution":"Released from rest means u = 0. Acceleration due to gravity is a different quantity.","difficulty":"Easy","topic":"Free fall","printed_pages":"50–51","explanation":"Released from rest means u = 0. Acceleration due to gravity is a different quantity."},{"id":"9th-ch2-026","number":26,"prompt":"A student walks 24 m east and 7 m west. What is the displacement?","options":["31 m west","17 m west","17 m east","31 m east"],"correct":2,"answer":"17 m east","solution":"Take east as positive: displacement = 24 − 7 = 17 m, directed east.","difficulty":"Medium","topic":"Distance and displacement","printed_pages":"37","explanation":"Take east as positive: displacement = 24 − 7 = 17 m, directed east."},{"id":"9th-ch2-027","number":27,"prompt":"A runner covers one 200 m lap in 40 s. What are average speed and magnitude of average velocity?","options":["5 m/s and 5 m/s","0 m/s and 5 m/s","5 m/s and 0 m/s","0 m/s and 0 m/s"],"correct":2,"answer":"5 m/s and 0 m/s","solution":"Average speed = 200 / 40 = 5 m/s. A complete lap gives zero displacement, hence zero average velocity.","difficulty":"Medium","topic":"Speed and velocity","printed_pages":"37–40","explanation":"Average speed = 200 / 40 = 5 m/s. A complete lap gives zero displacement, hence zero average velocity."},{"id":"9th-ch2-028","number":28,"prompt":"A car travels at 72 km/h. What is this speed in m/s?","options":["20 m/s","30 m/s","10 m/s","25 m/s"],"correct":0,"answer":"20 m/s","solution":"Convert using 1 km/h = 5/18 m/s: 72 × 5/18 = 20 m/s.","difficulty":"Medium","topic":"Speed and velocity","printed_pages":"38–40","explanation":"Convert using 1 km/h = 5/18 m/s: 72 × 5/18 = 20 m/s."},{"id":"9th-ch2-029","number":29,"prompt":"A cyclist travels 90 m in 15 s and then 60 m in 10 s. What is the average speed for the whole journey?","options":["10 m/s","5 m/s","6 m/s","12 m/s"],"correct":2,"answer":"6 m/s","solution":"Total distance = 150 m and total time = 25 s. Average speed = 150 / 25 = 6 m/s.","difficulty":"Medium","topic":"Speed and velocity","printed_pages":"38–40","explanation":"Total distance = 150 m and total time = 25 s. Average speed = 150 / 25 = 6 m/s."},{"id":"9th-ch2-030","number":30,"prompt":"A car moves around a circular track at constant speed. Which statement is correct?","options":["Its acceleration must be zero","Its displacement is always zero","Its velocity changes because its direction changes","Its velocity must be constant"],"correct":2,"answer":"Its velocity changes because its direction changes","solution":"Velocity includes direction. Changing direction changes velocity, even when speed stays constant.","difficulty":"Medium","topic":"Speed and velocity","printed_pages":"39–42","explanation":"Velocity includes direction. Changing direction changes velocity, even when speed stays constant."},{"id":"9th-ch2-031","number":31,"prompt":"Take east as positive. A car slows from +18 m/s to +6 m/s in 4 s. What is its acceleration?","options":["+6 m/s²","−3 m/s²","+3 m/s²","−6 m/s²"],"correct":1,"answer":"−3 m/s²","solution":"a = (6 − 18) / 4 = −3 m/s². Acceleration is opposite to the eastward velocity.","difficulty":"Medium","topic":"Acceleration","printed_pages":"41–43","explanation":"a = (6 − 18) / 4 = −3 m/s². Acceleration is opposite to the eastward velocity."},{"id":"9th-ch2-032","number":32,"prompt":"Take east as positive. A car changes velocity from −4 m/s to −10 m/s in 3 s. Which description is correct?","options":["It speeds up with acceleration +2 m/s²","It speeds up with acceleration −2 m/s²","It moves at constant velocity","It slows down with acceleration −2 m/s²"],"correct":1,"answer":"It speeds up with acceleration −2 m/s²","solution":"a = [−10 − (−4)] / 3 = −2 m/s². Speed increases from 4 to 10 m/s; a negative acceleration does not always mean slowing.","difficulty":"Medium","topic":"Acceleration","printed_pages":"41–43","explanation":"a = [−10 − (−4)] / 3 = −2 m/s². Speed increases from 4 to 10 m/s; a negative acceleration does not always mean slowing."},{"id":"9th-ch2-033","number":33,"prompt":"A straight distance–time graph rises from 10 m at 2 s to 50 m at 10 s. What is the speed?","options":["5 m/s","6.25 m/s","8 m/s","4 m/s"],"correct":0,"answer":"5 m/s","solution":"Speed = gradient = (50 − 10) / (10 − 2) = 40 / 8 = 5 m/s.","difficulty":"Medium","topic":"Motion graphs","printed_pages":"45–46","explanation":"Speed = gradient = (50 − 10) / (10 − 2) = 40 / 8 = 5 m/s."},{"id":"9th-ch2-034","number":34,"prompt":"A straight speed–time graph rises from 0 to 12 m/s in 6 s. What distance is travelled?","options":["2 m","18 m","72 m","36 m"],"correct":3,"answer":"36 m","solution":"Distance is the triangular area under the graph: ½ × 6 × 12 = 36 m.","difficulty":"Medium","topic":"Motion graphs","printed_pages":"46–47","explanation":"Distance is the triangular area under the graph: ½ × 6 × 12 = 36 m."},{"id":"9th-ch2-035","number":35,"prompt":"An object moves at a constant speed of 8 m/s for 5 s. What is the area under its speed–time graph?","options":["40 m","13 m","40 m/s²","1.6 m"],"correct":0,"answer":"40 m","solution":"The rectangular area is speed × time = 8 × 5 = 40 m, representing distance.","difficulty":"Medium","topic":"Motion graphs","printed_pages":"46–47","explanation":"The rectangular area is speed × time = 8 × 5 = 40 m, representing distance."},{"id":"9th-ch2-036","number":36,"prompt":"On a speed–time graph, speed falls uniformly from 20 m/s to 8 m/s in 4 s. What is the gradient?","options":["−3 m/s²","+7 m/s²","−7 m/s²","+3 m/s²"],"correct":0,"answer":"−3 m/s²","solution":"Gradient = (8 − 20) / 4 = −3 m/s². For straight-line motion in the positive direction, this is the acceleration.","difficulty":"Medium","topic":"Motion graphs","printed_pages":"46–47","explanation":"Gradient = (8 − 20) / 4 = −3 m/s². For straight-line motion in the positive direction, this is the acceleration."},{"id":"9th-ch2-037","number":37,"prompt":"A motorcycle starts from rest and accelerates uniformly at 3 m/s² for 4 s. What is its final speed?","options":["48 m/s","12 m/s","24 m/s","7 m/s"],"correct":1,"answer":"12 m/s","solution":"v = u + at = 0 + 3 × 4 = 12 m/s.","difficulty":"Medium","topic":"Equations of motion","printed_pages":"47–48","explanation":"v = u + at = 0 + 3 × 4 = 12 m/s."},{"id":"9th-ch2-038","number":38,"prompt":"A car has initial speed 5 m/s and constant acceleration 2 m/s² for 4 s. What distance does it travel?","options":["16 m","20 m","36 m","52 m"],"correct":2,"answer":"36 m","solution":"s = ut + ½at² = 5 × 4 + ½ × 2 × 4² = 20 + 16 = 36 m.","difficulty":"Medium","topic":"Equations of motion","printed_pages":"47–48","explanation":"s = ut + ½at² = 5 × 4 + ½ × 2 × 4² = 20 + 16 = 36 m."},{"id":"9th-ch2-039","number":39,"prompt":"A bicycle slows uniformly from 12 m/s to rest at 3 m/s². How long does it take to stop?","options":["9 s","6 s","3 s","4 s"],"correct":3,"answer":"4 s","solution":"Choose forward as positive: a = −3 m/s². t = (v − u) / a = (0 − 12) / (−3) = 4 s.","difficulty":"Medium","topic":"Equations of motion","printed_pages":"47–49","explanation":"Choose forward as positive: a = −3 m/s². t = (v − u) / a = (0 − 12) / (−3) = 4 s."},{"id":"9th-ch2-040","number":40,"prompt":"A car brakes uniformly from 20 m/s to rest with acceleration −5 m/s². What is its stopping distance?","options":["80 m","20 m","100 m","40 m"],"correct":3,"answer":"40 m","solution":"v² = u² + 2as gives 0 = 400 − 10s, so s = 40 m.","difficulty":"Medium","topic":"Equations of motion","printed_pages":"48–49","explanation":"v² = u² + 2as gives 0 = 400 − 10s, so s = 40 m."},{"id":"9th-ch2-041","number":41,"prompt":"A body starts from rest and travels 18 m in 3 s with uniform acceleration. What is its acceleration?","options":["6 m/s²","2 m/s²","4 m/s²","9 m/s²"],"correct":2,"answer":"4 m/s²","solution":"s = ½at² gives a = 2s/t² = 36/9 = 4 m/s².","difficulty":"Medium","topic":"Equations of motion","printed_pages":"47–48","explanation":"s = ½at² gives a = 2s/t² = 36/9 = 4 m/s²."},{"id":"9th-ch2-042","number":42,"prompt":"Which condition is required when using the three standard equations of uniformly accelerated motion?","options":["Acceleration remains constant","The object must fall vertically","Distance equals time","Speed remains zero"],"correct":0,"answer":"Acceleration remains constant","solution":"The equations assume constant acceleration during the interval; they also apply to suitable horizontal motion.","difficulty":"Medium","topic":"Equations of motion","printed_pages":"47–48","explanation":"The equations assume constant acceleration during the interval; they also apply to suitable horizontal motion."},{"id":"9th-ch2-043","number":43,"prompt":"A stone falls from rest for 3 s. Neglect air resistance and use g = 10 m/s². How far does it fall?","options":["15 m","45 m","30 m","90 m"],"correct":1,"answer":"45 m","solution":"s = ½gt² = ½ × 10 × 3² = 45 m downward.","difficulty":"Medium","topic":"Free fall","printed_pages":"50–52","explanation":"s = ½gt² = ½ × 10 × 3² = 45 m downward."},{"id":"9th-ch2-044","number":44,"prompt":"A ball is thrown vertically upward at 20 m/s. Use g = 10 m/s² and neglect air resistance. How long until it first reaches its highest point?","options":["2 s","1 s","10 s","4 s"],"correct":0,"answer":"2 s","solution":"At the highest point v = 0. Taking upward as positive, 0 = 20 − 10t, so t = 2 s.","difficulty":"Medium","topic":"Vertical motion","printed_pages":"50–52","explanation":"At the highest point v = 0. Taking upward as positive, 0 = 20 − 10t, so t = 2 s."},{"id":"9th-ch2-045","number":45,"prompt":"At the highest point of vertical flight, what are a ball's velocity and acceleration? Use upward as positive and neglect air resistance.","options":["v = 0 and a = 0","v = −g and a = g","v = g and a = 0","v = 0 and a = −g"],"correct":3,"answer":"v = 0 and a = −g","solution":"Velocity is momentarily zero, but gravity continues to provide downward acceleration a = −g.","difficulty":"Medium","topic":"Vertical motion","printed_pages":"50–52","explanation":"Velocity is momentarily zero, but gravity continues to provide downward acceleration a = −g."},{"id":"9th-ch2-046","number":46,"prompt":"A car travels equal distances at 10 m/s and 20 m/s. What is its average speed for the whole trip?","options":["12 m/s","30 m/s","15 m/s","13.3 m/s"],"correct":3,"answer":"13.3 m/s","solution":"Take each distance as 100 m. Times are 10 s and 5 s, so average speed = 200/15 = 13.3 m/s. Equal distances do not mean equal times.","difficulty":"Hard","topic":"Speed and velocity","printed_pages":"38–40","explanation":"Take each distance as 100 m. Times are 10 s and 5 s, so average speed = 200/15 = 13.3 m/s. Equal distances do not mean equal times."},{"id":"9th-ch2-047","number":47,"prompt":"A vehicle starts from rest, accelerates uniformly at 2 m/s² for 5 s, then keeps the attained speed for 3 s. What total distance does it travel?","options":["25 m","80 m","30 m","55 m"],"correct":3,"answer":"55 m","solution":"First v = 2 × 5 = 10 m/s and s₁ = ½ × 2 × 5² = 25 m. Then s₂ = 10 × 3 = 30 m. Total = 55 m.","difficulty":"Hard","topic":"Motion graphs and equations","printed_pages":"46–48","explanation":"First v = 2 × 5 = 10 m/s and s₁ = ½ × 2 × 5² = 25 m. Then s₂ = 10 × 3 = 30 m. Total = 55 m."},{"id":"9th-ch2-048","number":48,"prompt":"A car moving at 15 m/s travels for a 1 s reaction interval at constant speed, then brakes uniformly at 3 m/s² to rest. What total distance does it travel?","options":["52.5 m","37.5 m","15 m","75 m"],"correct":0,"answer":"52.5 m","solution":"Reaction distance = 15 × 1 = 15 m. Braking distance = u²/(2 × 3) = 225/6 = 37.5 m. Total = 52.5 m.","difficulty":"Hard","topic":"Equations of motion","printed_pages":"47–49","explanation":"Reaction distance = 15 × 1 = 15 m. Braking distance = u²/(2 × 3) = 225/6 = 37.5 m. Total = 52.5 m."},{"id":"9th-ch2-049","number":49,"prompt":"A speed–time graph rises uniformly from 0 to 8 m/s in 4 s, stays at 8 m/s for 3 s, then falls uniformly to zero in 2 s. What total distance is travelled?","options":["72 m","64 m","48 m","24 m"],"correct":2,"answer":"48 m","solution":"Add the three areas: ½ × 4 × 8 + 3 × 8 + ½ × 2 × 8 = 16 + 24 + 8 = 48 m.","difficulty":"Hard","topic":"Motion graphs","printed_pages":"46–47","explanation":"Add the three areas: ½ × 4 × 8 + 3 × 8 + ½ × 2 × 8 = 16 + 24 + 8 = 48 m."},{"id":"9th-ch2-050","number":50,"prompt":"A ball is thrown vertically upward at 30 m/s. Use g = 10 m/s² and neglect air resistance. What is its maximum height above the release point?","options":["30 m","90 m","60 m","45 m"],"correct":3,"answer":"45 m","solution":"At maximum height v = 0. Using 0 = 30² − 2 × 10 × h gives h = 900/20 = 45 m.","difficulty":"Hard","topic":"Vertical motion","printed_pages":"48, 50–52","explanation":"At maximum height v = 0. Using 0 = 30² − 2 × 10 × h gives h = 900/20 = 45 m."}],"cards":[{"id":"9th-ch2-001-card","topic":"Reference frames","prompt":"A passenger sitting in a moving bus is at rest relative to which object?","answer":"The bus seat","explanation":"The passenger and seat keep the same relative position, although both move relative to the road."},{"id":"9th-ch2-002-card","topic":"Reference frames","prompt":"Which statement best describes motion?","answer":"Position changes relative to a reference point with time","explanation":"Motion is a change of position with time relative to a chosen reference point."},{"id":"9th-ch2-003-card","topic":"Types of motion","prompt":"A train travels along a straight track. Its motion is mainly which type?","answer":"Linear motion","explanation":"Translation along a straight path is linear motion."},{"id":"9th-ch2-004-card","topic":"Types of motion","prompt":"A stone moves around a circle at the end of a string. Its motion around the hand is which type?","answer":"Circular motion","explanation":"The stone follows a circular path around a fixed centre."},{"id":"9th-ch2-005-card","topic":"Types of motion","prompt":"The irregular movement of a butterfly is an example of which motion?","answer":"Random motion","explanation":"An irregular path with unpredictable changes of direction is random motion."},{"id":"9th-ch2-006-card","topic":"Types of motion","prompt":"The spinning of a ceiling fan about its fixed axis is which motion?","answer":"Rotatory motion","explanation":"A body turning about its own fixed axis has rotatory motion."},{"id":"9th-ch2-007-card","topic":"Types of motion","prompt":"The repeated to-and-fro movement of a pendulum is which motion?","answer":"Vibratory motion","explanation":"A pendulum moves back and forth about its mean position, so its motion is vibratory."},{"id":"9th-ch2-008-card","topic":"Distance and displacement","prompt":"Which quantity describes the total length of a path travelled?","answer":"Distance","explanation":"Distance measures the complete path length, irrespective of direction."},{"id":"9th-ch2-009-card","topic":"Scalars and vectors","prompt":"Which quantity includes both magnitude and direction?","answer":"Displacement","explanation":"Displacement is a vector from the initial position to the final position."},{"id":"9th-ch2-010-card","topic":"Distance and displacement","prompt":"A student walks 30 m east and then 10 m west. What is the total distance travelled?","answer":"40 m","explanation":"Distance adds both path lengths: 30 + 10 = 40 m."},{"id":"9th-ch2-011-card","topic":"Distance and displacement","prompt":"A runner completes one full lap of a circular track and returns to the starting point. What is the displacement?","answer":"0 m","explanation":"Initial and final positions coincide, so displacement is zero even though distance is nonzero."},{"id":"9th-ch2-012-card","topic":"Scalars and vectors","prompt":"Which pair contains only scalar quantities?","answer":"Speed and time","explanation":"Speed and time need magnitude only; velocity, displacement and acceleration also have direction."},{"id":"9th-ch2-013-card","topic":"Vector representation","prompt":"In an arrow used to represent a vector, what does the arrowhead show?","answer":"Direction","explanation":"The arrowhead indicates vector direction; a chosen length scale represents magnitude."},{"id":"9th-ch2-014-card","topic":"Speed and velocity","prompt":"What is the SI unit of speed?","answer":"m/s","explanation":"Speed is distance divided by time, so its SI unit is metre per second."},{"id":"9th-ch2-015-card","topic":"Speed and velocity","prompt":"A cyclist travels 120 m in 20 s. What is the average speed?","answer":"6 m/s","explanation":"Average speed = total distance / total time = 120 / 20 = 6 m/s."},{"id":"9th-ch2-016-card","topic":"Speed and velocity","prompt":"Which relation defines average velocity?","answer":"Displacement divided by time interval","explanation":"Average velocity uses displacement, whereas average speed uses total distance."},{"id":"9th-ch2-017-card","topic":"Speed and velocity","prompt":"An object moves equal distances in equal time intervals. Its speed is described as what?","answer":"Uniform speed","explanation":"Uniform speed means that the distance covered per unit time remains constant."},{"id":"9th-ch2-018-card","topic":"Acceleration","prompt":"What is the SI unit of acceleration?","answer":"m/s²","explanation":"Acceleration is change in velocity divided by time: (m/s) / s = m/s²."},{"id":"9th-ch2-019-card","topic":"Acceleration","prompt":"Velocity increases from 4 m/s to 10 m/s in 3 s. What is the average acceleration?","answer":"2 m/s²","explanation":"a = (v − u) / t = (10 − 4) / 3 = 2 m/s²."},{"id":"9th-ch2-020-card","topic":"Acceleration","prompt":"An object moves with constant velocity. What is its acceleration?","answer":"Zero","explanation":"There is no change in either magnitude or direction of velocity, so acceleration is zero."},{"id":"9th-ch2-021-card","topic":"Motion graphs","prompt":"What does the gradient of a distance–time graph represent?","answer":"Speed","explanation":"Gradient = change in distance / change in time, which gives speed."},{"id":"9th-ch2-022-card","topic":"Motion graphs","prompt":"A horizontal line on a distance–time graph indicates what?","answer":"The object is at rest","explanation":"Distance is unchanged while time passes, so the object is at rest."},{"id":"9th-ch2-023-card","topic":"Equations of motion","prompt":"Which equation links initial velocity u, final velocity v, acceleration a and time t for constant acceleration?","answer":"v = u + at","explanation":"For constant acceleration, a = (v − u) / t rearranges to v = u + at."},{"id":"9th-ch2-024-card","topic":"Free fall","prompt":"What does free fall mean?","answer":"Motion under gravity alone","explanation":"A freely falling body is acted on only by gravity; air resistance is neglected."},{"id":"9th-ch2-025-card","topic":"Free fall","prompt":"A body is released from rest. What is its initial velocity?","answer":"0 m/s","explanation":"Released from rest means u = 0. Acceleration due to gravity is a different quantity."},{"id":"9th-ch2-026-card","topic":"Distance and displacement","prompt":"A student walks 24 m east and 7 m west. What is the displacement?","answer":"17 m east","explanation":"Take east as positive: displacement = 24 − 7 = 17 m, directed east."},{"id":"9th-ch2-027-card","topic":"Speed and velocity","prompt":"A runner covers one 200 m lap in 40 s. What are average speed and magnitude of average velocity?","answer":"5 m/s and 0 m/s","explanation":"Average speed = 200 / 40 = 5 m/s. A complete lap gives zero displacement, hence zero average velocity."},{"id":"9th-ch2-028-card","topic":"Speed and velocity","prompt":"A car travels at 72 km/h. What is this speed in m/s?","answer":"20 m/s","explanation":"Convert using 1 km/h = 5/18 m/s: 72 × 5/18 = 20 m/s."},{"id":"9th-ch2-029-card","topic":"Speed and velocity","prompt":"A cyclist travels 90 m in 15 s and then 60 m in 10 s. What is the average speed for the whole journey?","answer":"6 m/s","explanation":"Total distance = 150 m and total time = 25 s. Average speed = 150 / 25 = 6 m/s."},{"id":"9th-ch2-030-card","topic":"Speed and velocity","prompt":"A car moves around a circular track at constant speed. Which statement is correct?","answer":"Its velocity changes because its direction changes","explanation":"Velocity includes direction. Changing direction changes velocity, even when speed stays constant."},{"id":"9th-ch2-031-card","topic":"Acceleration","prompt":"Take east as positive. A car slows from +18 m/s to +6 m/s in 4 s. What is its acceleration?","answer":"−3 m/s²","explanation":"a = (6 − 18) / 4 = −3 m/s². Acceleration is opposite to the eastward velocity."},{"id":"9th-ch2-032-card","topic":"Acceleration","prompt":"Take east as positive. A car changes velocity from −4 m/s to −10 m/s in 3 s. Which description is correct?","answer":"It speeds up with acceleration −2 m/s²","explanation":"a = [−10 − (−4)] / 3 = −2 m/s². Speed increases from 4 to 10 m/s; a negative acceleration does not always mean slowing."},{"id":"9th-ch2-033-card","topic":"Motion graphs","prompt":"A straight distance–time graph rises from 10 m at 2 s to 50 m at 10 s. What is the speed?","answer":"5 m/s","explanation":"Speed = gradient = (50 − 10) / (10 − 2) = 40 / 8 = 5 m/s."},{"id":"9th-ch2-034-card","topic":"Motion graphs","prompt":"A straight speed–time graph rises from 0 to 12 m/s in 6 s. What distance is travelled?","answer":"36 m","explanation":"Distance is the triangular area under the graph: ½ × 6 × 12 = 36 m."},{"id":"9th-ch2-035-card","topic":"Motion graphs","prompt":"An object moves at a constant speed of 8 m/s for 5 s. What is the area under its speed–time graph?","answer":"40 m","explanation":"The rectangular area is speed × time = 8 × 5 = 40 m, representing distance."},{"id":"9th-ch2-036-card","topic":"Motion graphs","prompt":"On a speed–time graph, speed falls uniformly from 20 m/s to 8 m/s in 4 s. What is the gradient?","answer":"−3 m/s²","explanation":"Gradient = (8 − 20) / 4 = −3 m/s². For straight-line motion in the positive direction, this is the acceleration."},{"id":"9th-ch2-037-card","topic":"Equations of motion","prompt":"A motorcycle starts from rest and accelerates uniformly at 3 m/s² for 4 s. What is its final speed?","answer":"12 m/s","explanation":"v = u + at = 0 + 3 × 4 = 12 m/s."},{"id":"9th-ch2-038-card","topic":"Equations of motion","prompt":"A car has initial speed 5 m/s and constant acceleration 2 m/s² for 4 s. What distance does it travel?","answer":"36 m","explanation":"s = ut + ½at² = 5 × 4 + ½ × 2 × 4² = 20 + 16 = 36 m."},{"id":"9th-ch2-039-card","topic":"Equations of motion","prompt":"A bicycle slows uniformly from 12 m/s to rest at 3 m/s². How long does it take to stop?","answer":"4 s","explanation":"Choose forward as positive: a = −3 m/s². t = (v − u) / a = (0 − 12) / (−3) = 4 s."},{"id":"9th-ch2-040-card","topic":"Equations of motion","prompt":"A car brakes uniformly from 20 m/s to rest with acceleration −5 m/s². What is its stopping distance?","answer":"40 m","explanation":"v² = u² + 2as gives 0 = 400 − 10s, so s = 40 m."},{"id":"9th-ch2-041-card","topic":"Equations of motion","prompt":"A body starts from rest and travels 18 m in 3 s with uniform acceleration. What is its acceleration?","answer":"4 m/s²","explanation":"s = ½at² gives a = 2s/t² = 36/9 = 4 m/s²."},{"id":"9th-ch2-042-card","topic":"Equations of motion","prompt":"Which condition is required when using the three standard equations of uniformly accelerated motion?","answer":"Acceleration remains constant","explanation":"The equations assume constant acceleration during the interval; they also apply to suitable horizontal motion."},{"id":"9th-ch2-043-card","topic":"Free fall","prompt":"A stone falls from rest for 3 s. Neglect air resistance and use g = 10 m/s². How far does it fall?","answer":"45 m","explanation":"s = ½gt² = ½ × 10 × 3² = 45 m downward."},{"id":"9th-ch2-044-card","topic":"Vertical motion","prompt":"A ball is thrown vertically upward at 20 m/s. Use g = 10 m/s² and neglect air resistance. How long until it first reaches its highest point?","answer":"2 s","explanation":"At the highest point v = 0. Taking upward as positive, 0 = 20 − 10t, so t = 2 s."},{"id":"9th-ch2-045-card","topic":"Vertical motion","prompt":"At the highest point of vertical flight, what are a ball's velocity and acceleration? Use upward as positive and neglect air resistance.","answer":"v = 0 and a = −g","explanation":"Velocity is momentarily zero, but gravity continues to provide downward acceleration a = −g."},{"id":"9th-ch2-046-card","topic":"Speed and velocity","prompt":"A car travels equal distances at 10 m/s and 20 m/s. What is its average speed for the whole trip?","answer":"13.3 m/s","explanation":"Take each distance as 100 m. Times are 10 s and 5 s, so average speed = 200/15 = 13.3 m/s. Equal distances do not mean equal times."},{"id":"9th-ch2-047-card","topic":"Motion graphs and equations","prompt":"A vehicle starts from rest, accelerates uniformly at 2 m/s² for 5 s, then keeps the attained speed for 3 s. What total distance does it travel?","answer":"55 m","explanation":"First v = 2 × 5 = 10 m/s and s₁ = ½ × 2 × 5² = 25 m. Then s₂ = 10 × 3 = 30 m. Total = 55 m."},{"id":"9th-ch2-048-card","topic":"Equations of motion","prompt":"A car moving at 15 m/s travels for a 1 s reaction interval at constant speed, then brakes uniformly at 3 m/s² to rest. What total distance does it travel?","answer":"52.5 m","explanation":"Reaction distance = 15 × 1 = 15 m. Braking distance = u²/(2 × 3) = 225/6 = 37.5 m. Total = 52.5 m."},{"id":"9th-ch2-049-card","topic":"Motion graphs","prompt":"A speed–time graph rises uniformly from 0 to 8 m/s in 4 s, stays at 8 m/s for 3 s, then falls uniformly to zero in 2 s. What total distance is travelled?","answer":"48 m","explanation":"Add the three areas: ½ × 4 × 8 + 3 × 8 + ½ × 2 × 8 = 16 + 24 + 8 = 48 m."},{"id":"9th-ch2-050-card","topic":"Vertical motion","prompt":"A ball is thrown vertically upward at 30 m/s. Use g = 10 m/s² and neglect air resistance. What is its maximum height above the release point?","answer":"45 m","explanation":"At maximum height v = 0. Using 0 = 30² − 2 × 10 × h gives h = 900/20 = 45 m."}],"topics":[{"id":"Reference frames","name":"Reference frames"},{"id":"Types of motion","name":"Types of motion"},{"id":"Distance and displacement","name":"Distance and displacement"},{"id":"Scalars and vectors","name":"Scalars and vectors"},{"id":"Vector representation","name":"Vector representation"},{"id":"Speed and velocity","name":"Speed and velocity"},{"id":"Acceleration","name":"Acceleration"},{"id":"Motion graphs","name":"Motion graphs"},{"id":"Equations of motion","name":"Equations of motion"},{"id":"Free fall","name":"Free fall"},{"id":"Vertical motion","name":"Vertical motion"},{"id":"Motion graphs and equations","name":"Motion graphs and equations"}]},"10":{"title":"Sound","chapter":2,"mcqs":[{"id":"10th-ch2-001","number":1,"prompt":"What is the immediate source of sound from a tuning fork?","options":["Its colour","Its mass alone","Its vibrating prongs","Its temperature alone"],"correct":2,"answer":"Its vibrating prongs","solution":"The prongs vibrate and set nearby particles of the medium into vibration, producing sound.","difficulty":"Easy","topic":"Production of sound","printed_pages":"22","explanation":"The prongs vibrate and set nearby particles of the medium into vibration, producing sound."},{"id":"10th-ch2-002","number":2,"prompt":"Sound in air is mainly which type of wave?","options":["Longitudinal mechanical wave","Transverse light wave","Transverse electromagnetic wave","Longitudinal electromagnetic wave"],"correct":0,"answer":"Longitudinal mechanical wave","solution":"Air particles oscillate parallel to propagation, and a material medium is needed.","difficulty":"Easy","topic":"Nature of sound","printed_pages":"22–23","explanation":"Air particles oscillate parallel to propagation, and a material medium is needed."},{"id":"10th-ch2-003","number":3,"prompt":"In a sound wave in air, how do particles vibrate relative to the direction of wave travel?","options":["Always perpendicular to it","Parallel to it","Only in circles","They do not vibrate"],"correct":1,"answer":"Parallel to it","solution":"In a longitudinal wave, particle vibrations are parallel to the direction of wave propagation.","difficulty":"Easy","topic":"Nature of sound","printed_pages":"22–23","explanation":"In a longitudinal wave, particle vibrations are parallel to the direction of wave propagation."},{"id":"10th-ch2-004","number":4,"prompt":"What is a compression in a sound wave?","options":["A region of lower pressure and density","A region of higher pressure and density","A region with no particles","A region of zero temperature"],"correct":1,"answer":"A region of higher pressure and density","solution":"Particles are closer together in a compression, so pressure and density are higher than in neighbouring undisturbed air.","difficulty":"Easy","topic":"Compressions and rarefactions","printed_pages":"22–23","explanation":"Particles are closer together in a compression, so pressure and density are higher than in neighbouring undisturbed air."},{"id":"10th-ch2-005","number":5,"prompt":"What is a rarefaction in a sound wave?","options":["A region in which sound becomes light","A region of higher pressure and density","A region of lower pressure and density","A region containing no medium"],"correct":2,"answer":"A region of lower pressure and density","solution":"Particles are more spread out in a rarefaction; it is not a vacuum.","difficulty":"Easy","topic":"Compressions and rarefactions","printed_pages":"22–23","explanation":"Particles are more spread out in a rarefaction; it is not a vacuum."},{"id":"10th-ch2-006","number":6,"prompt":"Sound cannot travel through which region?","options":["Air","Steel","Water","A vacuum"],"correct":3,"answer":"A vacuum","solution":"Sound needs particles of a material medium to transfer mechanical vibrations.","difficulty":"Easy","topic":"Medium","printed_pages":"23","explanation":"Sound needs particles of a material medium to transfer mechanical vibrations."},{"id":"10th-ch2-007","number":7,"prompt":"As air is removed from a bell jar containing a ringing electric bell, what happens to the heard sound?","options":["Its speed becomes the speed of light","It stays equally loud in a vacuum","It becomes louder indefinitely","It becomes fainter"],"correct":3,"answer":"It becomes fainter","solution":"Removing air reduces the medium available to transmit the bell's vibrations to the listener.","difficulty":"Easy","topic":"Medium","printed_pages":"23","explanation":"Removing air reduces the medium available to transmit the bell's vibrations to the listener."},{"id":"10th-ch2-008","number":8,"prompt":"During sound propagation, what is transferred through the medium?","options":["Only the source's mass","All particles permanently from source to listener","Energy","Only electric charge"],"correct":2,"answer":"Energy","solution":"Particles vibrate about their equilibrium positions and pass energy to neighbouring particles.","difficulty":"Easy","topic":"Nature of sound","printed_pages":"22–23","explanation":"Particles vibrate about their equilibrium positions and pass energy to neighbouring particles."},{"id":"10th-ch2-009","number":9,"prompt":"What is the distance between two consecutive compressions called?","options":["Time period","Amplitude","Wavelength","Loudness"],"correct":2,"answer":"Wavelength","solution":"Consecutive compressions are points at the same stage of vibration, one wavelength apart.","difficulty":"Easy","topic":"Wavelength","printed_pages":"26, 38","explanation":"Consecutive compressions are points at the same stage of vibration, one wavelength apart."},{"id":"10th-ch2-010","number":10,"prompt":"Which equation relates sound speed v, frequency f and wavelength λ?","options":["v = fλ","v = f + λ","v = f/λ","v = λ/f"],"correct":0,"answer":"v = fλ","solution":"One wavelength is travelled per period; since f = 1/T, v = λ/T = fλ.","difficulty":"Easy","topic":"Sound speed","printed_pages":"26","explanation":"One wavelength is travelled per period; since f = 1/T, v = λ/T = fλ."},{"id":"10th-ch2-011","number":11,"prompt":"What is the SI unit of frequency?","options":["Metre","Hertz","Watt","Second"],"correct":1,"answer":"Hertz","solution":"Frequency counts oscillations per second and is measured in hertz, Hz.","difficulty":"Easy","topic":"Frequency","printed_pages":"26, 33","explanation":"Frequency counts oscillations per second and is measured in hertz, Hz."},{"id":"10th-ch2-012","number":12,"prompt":"For typical conditions, which order lists sound speed from highest to lowest in steel, water and air?","options":["Air then water then steel","Steel then water then air","Water then steel then air","Air then steel then water"],"correct":1,"answer":"Steel then water then air","solution":"For the representative materials in the chapter, sound travels fastest in steel and slowest in air.","difficulty":"Easy","topic":"Sound speed","printed_pages":"26–27","explanation":"For the representative materials in the chapter, sound travels fastest in steel and slowest in air."},{"id":"10th-ch2-013","number":13,"prompt":"What generally happens to the speed of sound in air when its temperature rises?","options":["It increases","It becomes zero","It always decreases","It becomes independent of the medium"],"correct":0,"answer":"It increases","solution":"For air of fixed composition, higher temperature increases sound speed.","difficulty":"Easy","topic":"Temperature and humidity","printed_pages":"27–29","explanation":"For air of fixed composition, higher temperature increases sound speed."},{"id":"10th-ch2-014","number":14,"prompt":"At the same temperature, increasing the humidity of air generally has which effect on sound speed?","options":["It changes sound into light","It increases slightly","It makes sound unable to travel","It reduces the speed to zero"],"correct":1,"answer":"It increases slightly","solution":"More water vapour changes air composition; the chapter states that sound travels slightly faster in more humid air.","difficulty":"Easy","topic":"Temperature and humidity","printed_pages":"28","explanation":"More water vapour changes air composition; the chapter states that sound travels slightly faster in more humid air."},{"id":"10th-ch2-015","number":15,"prompt":"Which characteristic mainly determines the pitch of a sound?","options":["Frequency","Travel time alone","Amplitude","Distance from the source alone"],"correct":0,"answer":"Frequency","solution":"A higher frequency is heard as a higher pitch.","difficulty":"Easy","topic":"Pitch","printed_pages":"29–30","explanation":"A higher frequency is heard as a higher pitch."},{"id":"10th-ch2-016","number":16,"prompt":"Which change makes the sound of a tuning fork louder, with its frequency unchanged?","options":["Reducing frequency to zero","Removing the surrounding air","Increasing vibration amplitude","Decreasing vibration amplitude"],"correct":2,"answer":"Increasing vibration amplitude","solution":"Larger amplitude produces a louder sound under the same listening conditions.","difficulty":"Easy","topic":"Loudness","printed_pages":"29–31","explanation":"Larger amplitude produces a louder sound under the same listening conditions."},{"id":"10th-ch2-017","number":17,"prompt":"Which characteristic helps distinguish two instruments playing the same note at the same loudness?","options":["The listener's distance alone","Frequency alone","Quality or timbre","Speed of sound in the room"],"correct":2,"answer":"Quality or timbre","solution":"Different waveforms and mixtures of overtones give instruments different quality or timbre.","difficulty":"Easy","topic":"Quality of sound","printed_pages":"29–30","explanation":"Different waveforms and mixtures of overtones give instruments different quality or timbre."},{"id":"10th-ch2-018","number":18,"prompt":"What is sound intensity defined as?","options":["Pressure multiplied by time","Sound frequency per unit time","Wavelength per unit area","Sound power per unit area"],"correct":3,"answer":"Sound power per unit area","solution":"Intensity is the rate of sound energy transfer per unit area normal to propagation: I = P/A.","difficulty":"Easy","topic":"Intensity","printed_pages":"30–31","explanation":"Intensity is the rate of sound energy transfer per unit area normal to propagation: I = P/A."},{"id":"10th-ch2-019","number":19,"prompt":"What is the SI unit of sound intensity?","options":["Hz","m/s","W·m²","W/m²"],"correct":3,"answer":"W/m²","solution":"Power is in watts and area in square metres, so intensity is in W/m².","difficulty":"Easy","topic":"Intensity","printed_pages":"30–31","explanation":"Power is in watts and area in square metres, so intensity is in W/m²."},{"id":"10th-ch2-020","number":20,"prompt":"An unwanted sound that causes disturbance is called what?","options":["Noise","An echo only","A compression only","Ultrasound only"],"correct":0,"answer":"Noise","solution":"Noise is unwanted sound; whether a sound is unwanted can depend on the listener and situation.","difficulty":"Easy","topic":"Noise","printed_pages":"30–31","explanation":"Noise is unwanted sound; whether a sound is unwanted can depend on the listener and situation."},{"id":"10th-ch2-021","number":21,"prompt":"Which action helps reduce traffic noise reaching a classroom?","options":["Placing loudspeakers beside the windows","Removing all walls","Installing a suitable sound barrier","Sounding more vehicle horns"],"correct":2,"answer":"Installing a suitable sound barrier","solution":"A suitable barrier reduces the sound transmitted from traffic to the classroom.","difficulty":"Easy","topic":"Noise control","printed_pages":"31","explanation":"A suitable barrier reduces the sound transmitted from traffic to the classroom."},{"id":"10th-ch2-022","number":22,"prompt":"An echo is caused mainly by which process?","options":["Conversion of sound into light","Absence of a medium","Evaporation of air","Reflection of sound"],"correct":3,"answer":"Reflection of sound","solution":"An echo is reflected sound that returns to the listener after a sufficient delay.","difficulty":"Easy","topic":"Echo","printed_pages":"32","explanation":"An echo is reflected sound that returns to the listener after a sufficient delay."},{"id":"10th-ch2-023","number":23,"prompt":"What is the approximate audible frequency range of a young person with normal hearing?","options":["200 Hz to 2,000 Hz only","20 Hz to 20,000 Hz","2 Hz to 20 Hz","20,000 Hz to 200,000 Hz"],"correct":1,"answer":"20 Hz to 20,000 Hz","solution":"The conventional human audible range is approximately 20 Hz to 20 kHz; actual hearing varies between people.","difficulty":"Easy","topic":"Audible range","printed_pages":"33","explanation":"The conventional human audible range is approximately 20 Hz to 20 kHz; actual hearing varies between people."},{"id":"10th-ch2-024","number":24,"prompt":"Sound with frequency above 20,000 Hz is called what?","options":["A radio wave","Ultrasound","Ordinary audible sound for all humans","Infrasound"],"correct":1,"answer":"Ultrasound","solution":"Ultrasound lies above the conventional upper limit of human hearing.","difficulty":"Easy","topic":"Ultrasound","printed_pages":"33","explanation":"Ultrasound lies above the conventional upper limit of human hearing."},{"id":"10th-ch2-025","number":25,"prompt":"Sound with frequency below 20 Hz is called what?","options":["Infrasound","An X-ray","Ultrasound","Microwave radiation"],"correct":0,"answer":"Infrasound","solution":"Infrasound lies below the conventional lower limit of human hearing.","difficulty":"Easy","topic":"Audible range","printed_pages":"33","explanation":"Infrasound lies below the conventional lower limit of human hearing."},{"id":"10th-ch2-026","number":26,"prompt":"A sound wave has frequency 500 Hz and wavelength 0.68 m. What is its speed?","options":["735 m/s","340 m/s","500 m/s","250 m/s"],"correct":1,"answer":"340 m/s","solution":"v = fλ = 500 × 0.68 = 340 m/s.","difficulty":"Medium","topic":"Sound speed","printed_pages":"26–29","explanation":"v = fλ = 500 × 0.68 = 340 m/s."},{"id":"10th-ch2-027","number":27,"prompt":"Sound travels at 340 m/s and has frequency 850 Hz. What is its wavelength?","options":["0.25 m","2.5 m","4.0 m","0.40 m"],"correct":3,"answer":"0.40 m","solution":"λ = v/f = 340/850 = 0.40 m.","difficulty":"Medium","topic":"Wavelength","printed_pages":"26–29","explanation":"λ = v/f = 340/850 = 0.40 m."},{"id":"10th-ch2-028","number":28,"prompt":"A sound wave has a period of 0.002 s. What is its frequency?","options":["500 Hz","2,000 Hz","200 Hz","50 Hz"],"correct":0,"answer":"500 Hz","solution":"f = 1/T = 1/0.002 = 500 Hz.","difficulty":"Medium","topic":"Frequency","printed_pages":"26","explanation":"f = 1/T = 1/0.002 = 500 Hz."},{"id":"10th-ch2-029","number":29,"prompt":"At a fixed air temperature, the frequency of a sound is doubled. What happens to its wavelength?","options":["It is halved","It is unchanged","It is doubled","It becomes zero"],"correct":0,"answer":"It is halved","solution":"For sound in the same air under unchanged conditions, speed stays approximately constant. Since λ = v/f, doubling f halves λ.","difficulty":"Medium","topic":"Wavelength","printed_pages":"26–27","explanation":"For sound in the same air under unchanged conditions, speed stays approximately constant. Since λ = v/f, doubling f halves λ."},{"id":"10th-ch2-030","number":30,"prompt":"Two students are 170 m apart. Sound travels at 340 m/s. What is the sound travel time between them?","options":["0.50 s","5.0 s","0.25 s","2.0 s"],"correct":0,"answer":"0.50 s","solution":"t = d/v = 170/340 = 0.50 s. A direct path uses d, not 2d.","difficulty":"Medium","topic":"Measuring sound speed","printed_pages":"24–25","explanation":"t = d/v = 170/340 = 0.50 s. A direct path uses d, not 2d."},{"id":"10th-ch2-031","number":31,"prompt":"A listener stands 51 m from a large reflecting wall. If sound speed is 340 m/s, how long after a clap does its echo return?","options":["3.0 s","0.15 s","0.60 s","0.30 s"],"correct":3,"answer":"0.30 s","solution":"Sound travels to the wall and back: t = 2d/v = 102/340 = 0.30 s.","difficulty":"Medium","topic":"Echo","printed_pages":"25, 32","explanation":"Sound travels to the wall and back: t = 2d/v = 102/340 = 0.30 s."},{"id":"10th-ch2-032","number":32,"prompt":"An echo returns 0.40 s after a shout. Sound speed is 340 m/s. How far away is the reflecting surface?","options":["34 m","85 m","136 m","68 m"],"correct":3,"answer":"68 m","solution":"The echo time is for the round trip. d = vt/2 = 340 × 0.40 / 2 = 68 m.","difficulty":"Medium","topic":"Echo","printed_pages":"32","explanation":"The echo time is for the round trip. d = vt/2 = 340 × 0.40 / 2 = 68 m."},{"id":"10th-ch2-033","number":33,"prompt":"Assume a separate echo requires at least 0.10 s delay. At sound speed 340 m/s, what is the minimum distance to a reflecting wall?","options":["3.4 m","170 m","34 m","17 m"],"correct":3,"answer":"17 m","solution":"The round-trip path must be at least 340 × 0.10 = 34 m, so the wall must be at least 17 m away.","difficulty":"Medium","topic":"Echo","printed_pages":"32","explanation":"The round-trip path must be at least 340 × 0.10 = 34 m, so the wall must be at least 17 m away."},{"id":"10th-ch2-034","number":34,"prompt":"A sound source transfers 0.60 W through an area of 3.0 m² normal to propagation. What is the intensity?","options":["0.20 W/m²","0.60 W/m²","5.0 W/m²","1.8 W/m²"],"correct":0,"answer":"0.20 W/m²","solution":"I = P/A = 0.60/3.0 = 0.20 W/m².","difficulty":"Medium","topic":"Intensity","printed_pages":"30–31","explanation":"I = P/A = 0.60/3.0 = 0.20 W/m²."},{"id":"10th-ch2-035","number":35,"prompt":"Two oscilloscope traces have the same time scale. Trace A shows 8 cycles and B shows 4 cycles in the same interval. Which sound has the higher pitch?","options":["B, because its frequency is higher","Pitch cannot depend on cycle count","Both must have the same pitch","A, because its frequency is higher"],"correct":3,"answer":"A, because its frequency is higher","solution":"A completes twice as many cycles per unit time, so its frequency and pitch are higher.","difficulty":"Medium","topic":"Pitch and waveforms","printed_pages":"29–30","explanation":"A completes twice as many cycles per unit time, so its frequency and pitch are higher."},{"id":"10th-ch2-036","number":36,"prompt":"Two sounds have the same frequency and amplitude but different waveforms. Which characteristic differs?","options":["Quality or timbre","Frequency necessarily","Sound speed necessarily","Pitch necessarily"],"correct":0,"answer":"Quality or timbre","solution":"Waveform differences at the same frequency and amplitude indicate different quality or timbre.","difficulty":"Medium","topic":"Quality of sound","printed_pages":"29–30","explanation":"Waveform differences at the same frequency and amplitude indicate different quality or timbre."},{"id":"10th-ch2-037","number":37,"prompt":"Which pair consists of one infrasonic and one ultrasonic frequency, respectively?","options":["25 Hz and 15,000 Hz","25,000 Hz and 15 Hz","15 Hz and 25,000 Hz","150 Hz and 2,500 Hz"],"correct":2,"answer":"15 Hz and 25,000 Hz","solution":"15 Hz is below 20 Hz and 25,000 Hz is above 20,000 Hz, so the pair is infrasonic then ultrasonic.","difficulty":"Medium","topic":"Audible range","printed_pages":"33","explanation":"15 Hz is below 20 Hz and 25,000 Hz is above 20,000 Hz, so the pair is infrasonic then ultrasonic."},{"id":"10th-ch2-038","number":38,"prompt":"Sound travels in water at 1,500 m/s. A SONAR pulse returns from the seabed after 0.20 s. What is the water depth?","options":["75 m","300 m","150 m","30 m"],"correct":2,"answer":"150 m","solution":"Depth = vt/2 = 1,500 × 0.20 / 2 = 150 m. The pulse makes a round trip.","difficulty":"Medium","topic":"SONAR","printed_pages":"34","explanation":"Depth = vt/2 = 1,500 × 0.20 / 2 = 150 m. The pulse makes a round trip."},{"id":"10th-ch2-039","number":39,"prompt":"An ultrasonic pulse in soft tissue has speed 1,540 m/s. It returns from a boundary after 0.00010 s. How deep is the boundary?","options":["0.770 m","0.0154 m","0.154 m","0.077 m"],"correct":3,"answer":"0.077 m","solution":"Depth = vt/2 = 1,540 × 0.00010 / 2 = 0.077 m, or 7.7 cm.","difficulty":"Medium","topic":"Medical ultrasound","printed_pages":"34–35","explanation":"Depth = vt/2 = 1,540 × 0.00010 / 2 = 0.077 m, or 7.7 cm."},{"id":"10th-ch2-040","number":40,"prompt":"An ultrasound detector receives an unexpected early reflected pulse from inside a metal block. What can this indicate?","options":["The absence of all matter in the block","A change of ultrasound into radio waves","That ultrasound cannot enter metal","An internal crack or flaw"],"correct":3,"answer":"An internal crack or flaw","solution":"An internal defect can reflect ultrasound before the far surface does, allowing the defect to be located.","difficulty":"Medium","topic":"Industrial ultrasound","printed_pages":"34","explanation":"An internal defect can reflect ultrasound before the far surface does, allowing the defect to be located."},{"id":"10th-ch2-041","number":41,"prompt":"In ultrasonic cleaning, why can dirt be removed from small inaccessible spaces?","options":["Ultrasound eliminates the need for any liquid","Ultrasound changes dirt into light","Ultrasonic vibrations in the cleaning liquid help detach dirt","Sound travels only on the outer surface"],"correct":2,"answer":"Ultrasonic vibrations in the cleaning liquid help detach dirt","solution":"Ultrasound produces rapid mechanical action in the cleaning liquid that loosens contaminants, including in small spaces.","difficulty":"Medium","topic":"Industrial ultrasound","printed_pages":"34","explanation":"Ultrasound produces rapid mechanical action in the cleaning liquid that loosens contaminants, including in small spaces."},{"id":"10th-ch2-042","number":42,"prompt":"Which technique uses reflected ultrasound to form images of the heart and its valves?","options":["Optical dispersion","Echocardiography","Radio broadcasting","Electrostatic charging"],"correct":1,"answer":"Echocardiography","solution":"Echocardiography uses echoes of ultrasonic pulses to produce images of heart structures.","difficulty":"Medium","topic":"Medical ultrasound","printed_pages":"34–35","explanation":"Echocardiography uses echoes of ultrasonic pulses to produce images of heart structures."},{"id":"10th-ch2-043","number":43,"prompt":"A distant flash is seen before its associated sound is heard. What is the main reason?","options":["Light travels much faster than sound in air","Light needs air but sound does not","Sound travels faster than light","Sound is produced only when light arrives"],"correct":0,"answer":"Light travels much faster than sound in air","solution":"The travel time of light is negligible compared with sound over ordinary distances, so the flash is seen first.","difficulty":"Medium","topic":"Measuring sound speed","printed_pages":"24–25, 35","explanation":"The travel time of light is negligible compared with sound over ordinary distances, so the flash is seen first."},{"id":"10th-ch2-044","number":44,"prompt":"During a direct sound-speed measurement, why is a relatively large separation between source and observer useful?","options":["It increases the actual sound speed","It makes sound travel through a vacuum","It makes the sound travel time easier to measure","It removes the need to measure distance"],"correct":2,"answer":"It makes the sound travel time easier to measure","solution":"A longer path increases the travel time, reducing the relative effect of timing uncertainty. Distance and time are still both required.","difficulty":"Medium","topic":"Measuring sound speed","printed_pages":"24–25","explanation":"A longer path increases the travel time, reducing the relative effect of timing uncertainty. Distance and time are still both required."},{"id":"10th-ch2-045","number":45,"prompt":"A bat emits sound of wavelength 0.0085 m in air where its speed is 340 m/s. How is the sound classified?","options":["Audible, at 4,000 Hz","Audible, at 400 Hz","Ultrasonic, at 40,000 Hz","Infrasonic, at 4 Hz"],"correct":2,"answer":"Ultrasonic, at 40,000 Hz","solution":"f = v/λ = 340/0.0085 = 40,000 Hz. This exceeds 20,000 Hz, so it is ultrasound.","difficulty":"Medium","topic":"Ultrasound and wavelength","printed_pages":"26, 33, 40","explanation":"f = v/λ = 340/0.0085 = 40,000 Hz. This exceeds 20,000 Hz, so it is ultrasound."},{"id":"10th-ch2-046","number":46,"prompt":"A sound wave has frequency 680 Hz and wavelength 0.50 m. Its echo returns after 0.60 s. How far away is the reflecting wall?","options":["51 m","102 m","340 m","204 m"],"correct":1,"answer":"102 m","solution":"First v = fλ = 680 × 0.50 = 340 m/s. Then d = vt/2 = 340 × 0.60 / 2 = 102 m.","difficulty":"Hard","topic":"Sound speed and echo","printed_pages":"26, 32","explanation":"First v = fλ = 680 × 0.50 = 340 m/s. Then d = vt/2 = 340 × 0.60 / 2 = 102 m."},{"id":"10th-ch2-047","number":47,"prompt":"A person is 85 m from a wall. The total time for 20 complete sound round trips between person and wall is 10 s. What sound speed is measured?","options":["340 m/s","170 m/s","34 m/s","850 m/s"],"correct":0,"answer":"340 m/s","solution":"Each round trip covers 2 × 85 = 170 m. Total path = 20 × 170 = 3,400 m. Speed = 3,400/10 = 340 m/s.","difficulty":"Hard","topic":"Measuring sound speed","printed_pages":"25","explanation":"Each round trip covers 2 × 85 = 170 m. Total path = 20 × 170 = 3,400 m. Speed = 3,400/10 = 340 m/s."},{"id":"10th-ch2-048","number":48,"prompt":"A ship measures the water depth at two positions using SONAR. The seabed echo returns after 0.12 s at the first position and 0.20 s at the second. Sound speed in water is 1,500 m/s. How much greater is the second depth?","options":["120 m","60 m","90 m","150 m"],"correct":1,"answer":"60 m","solution":"First depth = 1,500 × 0.12 / 2 = 90 m. Second depth = 1,500 × 0.20 / 2 = 150 m. The second depth is 150 − 90 = 60 m greater.","difficulty":"Hard","topic":"SONAR","printed_pages":"34, 40","explanation":"First depth = 1,500 × 0.12 / 2 = 90 m. Second depth = 1,500 × 0.20 / 2 = 150 m. The second depth is 150 − 90 = 60 m greater."},{"id":"10th-ch2-049","number":49,"prompt":"In the same gas, use v₂/v₁ = √(T₂/T₁), with absolute temperatures. If sound speed is 330 m/s at 273 K, what is it at 1,092 K?","options":["330 m/s","660 m/s","165 m/s","1,320 m/s"],"correct":1,"answer":"660 m/s","solution":"T₂/T₁ = 1,092/273 = 4. Thus v₂/v₁ = √4 = 2 and v₂ = 660 m/s. Temperatures must be in kelvin.","difficulty":"Hard","topic":"Temperature and sound speed","printed_pages":"27–29","explanation":"T₂/T₁ = 1,092/273 = 4. Thus v₂/v₁ = √4 = 2 and v₂ = 660 m/s. Temperatures must be in kelvin."},{"id":"10th-ch2-050","number":50,"prompt":"An ultrasonic pulse travels through tissue at 1,500 m/s with frequency 3.0 MHz. What is its wavelength?","options":["5.0 mm","0.50 mm","50 mm","0.05 mm"],"correct":1,"answer":"0.50 mm","solution":"3.0 MHz = 3,000,000 Hz. λ = 1,500/3,000,000 = 0.00050 m = 0.50 mm.","difficulty":"Hard","topic":"Medical ultrasound and wavelength","printed_pages":"26, 33–35","explanation":"3.0 MHz = 3,000,000 Hz. λ = 1,500/3,000,000 = 0.00050 m = 0.50 mm."}],"cards":[{"id":"10th-ch2-001-card","topic":"Production of sound","prompt":"What is the immediate source of sound from a tuning fork?","answer":"Its vibrating prongs","explanation":"The prongs vibrate and set nearby particles of the medium into vibration, producing sound."},{"id":"10th-ch2-002-card","topic":"Nature of sound","prompt":"Sound in air is mainly which type of wave?","answer":"Longitudinal mechanical wave","explanation":"Air particles oscillate parallel to propagation, and a material medium is needed."},{"id":"10th-ch2-003-card","topic":"Nature of sound","prompt":"In a sound wave in air, how do particles vibrate relative to the direction of wave travel?","answer":"Parallel to it","explanation":"In a longitudinal wave, particle vibrations are parallel to the direction of wave propagation."},{"id":"10th-ch2-004-card","topic":"Compressions and rarefactions","prompt":"What is a compression in a sound wave?","answer":"A region of higher pressure and density","explanation":"Particles are closer together in a compression, so pressure and density are higher than in neighbouring undisturbed air."},{"id":"10th-ch2-005-card","topic":"Compressions and rarefactions","prompt":"What is a rarefaction in a sound wave?","answer":"A region of lower pressure and density","explanation":"Particles are more spread out in a rarefaction; it is not a vacuum."},{"id":"10th-ch2-006-card","topic":"Medium","prompt":"Sound cannot travel through which region?","answer":"A vacuum","explanation":"Sound needs particles of a material medium to transfer mechanical vibrations."},{"id":"10th-ch2-007-card","topic":"Medium","prompt":"As air is removed from a bell jar containing a ringing electric bell, what happens to the heard sound?","answer":"It becomes fainter","explanation":"Removing air reduces the medium available to transmit the bell's vibrations to the listener."},{"id":"10th-ch2-008-card","topic":"Nature of sound","prompt":"During sound propagation, what is transferred through the medium?","answer":"Energy","explanation":"Particles vibrate about their equilibrium positions and pass energy to neighbouring particles."},{"id":"10th-ch2-009-card","topic":"Wavelength","prompt":"What is the distance between two consecutive compressions called?","answer":"Wavelength","explanation":"Consecutive compressions are points at the same stage of vibration, one wavelength apart."},{"id":"10th-ch2-010-card","topic":"Sound speed","prompt":"Which equation relates sound speed v, frequency f and wavelength λ?","answer":"v = fλ","explanation":"One wavelength is travelled per period; since f = 1/T, v = λ/T = fλ."},{"id":"10th-ch2-011-card","topic":"Frequency","prompt":"What is the SI unit of frequency?","answer":"Hertz","explanation":"Frequency counts oscillations per second and is measured in hertz, Hz."},{"id":"10th-ch2-012-card","topic":"Sound speed","prompt":"For typical conditions, which order lists sound speed from highest to lowest in steel, water and air?","answer":"Steel then water then air","explanation":"For the representative materials in the chapter, sound travels fastest in steel and slowest in air."},{"id":"10th-ch2-013-card","topic":"Temperature and humidity","prompt":"What generally happens to the speed of sound in air when its temperature rises?","answer":"It increases","explanation":"For air of fixed composition, higher temperature increases sound speed."},{"id":"10th-ch2-014-card","topic":"Temperature and humidity","prompt":"At the same temperature, increasing the humidity of air generally has which effect on sound speed?","answer":"It increases slightly","explanation":"More water vapour changes air composition; the chapter states that sound travels slightly faster in more humid air."},{"id":"10th-ch2-015-card","topic":"Pitch","prompt":"Which characteristic mainly determines the pitch of a sound?","answer":"Frequency","explanation":"A higher frequency is heard as a higher pitch."},{"id":"10th-ch2-016-card","topic":"Loudness","prompt":"Which change makes the sound of a tuning fork louder, with its frequency unchanged?","answer":"Increasing vibration amplitude","explanation":"Larger amplitude produces a louder sound under the same listening conditions."},{"id":"10th-ch2-017-card","topic":"Quality of sound","prompt":"Which characteristic helps distinguish two instruments playing the same note at the same loudness?","answer":"Quality or timbre","explanation":"Different waveforms and mixtures of overtones give instruments different quality or timbre."},{"id":"10th-ch2-018-card","topic":"Intensity","prompt":"What is sound intensity defined as?","answer":"Sound power per unit area","explanation":"Intensity is the rate of sound energy transfer per unit area normal to propagation: I = P/A."},{"id":"10th-ch2-019-card","topic":"Intensity","prompt":"What is the SI unit of sound intensity?","answer":"W/m²","explanation":"Power is in watts and area in square metres, so intensity is in W/m²."},{"id":"10th-ch2-020-card","topic":"Noise","prompt":"An unwanted sound that causes disturbance is called what?","answer":"Noise","explanation":"Noise is unwanted sound; whether a sound is unwanted can depend on the listener and situation."},{"id":"10th-ch2-021-card","topic":"Noise control","prompt":"Which action helps reduce traffic noise reaching a classroom?","answer":"Installing a suitable sound barrier","explanation":"A suitable barrier reduces the sound transmitted from traffic to the classroom."},{"id":"10th-ch2-022-card","topic":"Echo","prompt":"An echo is caused mainly by which process?","answer":"Reflection of sound","explanation":"An echo is reflected sound that returns to the listener after a sufficient delay."},{"id":"10th-ch2-023-card","topic":"Audible range","prompt":"What is the approximate audible frequency range of a young person with normal hearing?","answer":"20 Hz to 20,000 Hz","explanation":"The conventional human audible range is approximately 20 Hz to 20 kHz; actual hearing varies between people."},{"id":"10th-ch2-024-card","topic":"Ultrasound","prompt":"Sound with frequency above 20,000 Hz is called what?","answer":"Ultrasound","explanation":"Ultrasound lies above the conventional upper limit of human hearing."},{"id":"10th-ch2-025-card","topic":"Audible range","prompt":"Sound with frequency below 20 Hz is called what?","answer":"Infrasound","explanation":"Infrasound lies below the conventional lower limit of human hearing."},{"id":"10th-ch2-026-card","topic":"Sound speed","prompt":"A sound wave has frequency 500 Hz and wavelength 0.68 m. What is its speed?","answer":"340 m/s","explanation":"v = fλ = 500 × 0.68 = 340 m/s."},{"id":"10th-ch2-027-card","topic":"Wavelength","prompt":"Sound travels at 340 m/s and has frequency 850 Hz. What is its wavelength?","answer":"0.40 m","explanation":"λ = v/f = 340/850 = 0.40 m."},{"id":"10th-ch2-028-card","topic":"Frequency","prompt":"A sound wave has a period of 0.002 s. What is its frequency?","answer":"500 Hz","explanation":"f = 1/T = 1/0.002 = 500 Hz."},{"id":"10th-ch2-029-card","topic":"Wavelength","prompt":"At a fixed air temperature, the frequency of a sound is doubled. What happens to its wavelength?","answer":"It is halved","explanation":"For sound in the same air under unchanged conditions, speed stays approximately constant. Since λ = v/f, doubling f halves λ."},{"id":"10th-ch2-030-card","topic":"Measuring sound speed","prompt":"Two students are 170 m apart. Sound travels at 340 m/s. What is the sound travel time between them?","answer":"0.50 s","explanation":"t = d/v = 170/340 = 0.50 s. A direct path uses d, not 2d."},{"id":"10th-ch2-031-card","topic":"Echo","prompt":"A listener stands 51 m from a large reflecting wall. If sound speed is 340 m/s, how long after a clap does its echo return?","answer":"0.30 s","explanation":"Sound travels to the wall and back: t = 2d/v = 102/340 = 0.30 s."},{"id":"10th-ch2-032-card","topic":"Echo","prompt":"An echo returns 0.40 s after a shout. Sound speed is 340 m/s. How far away is the reflecting surface?","answer":"68 m","explanation":"The echo time is for the round trip. d = vt/2 = 340 × 0.40 / 2 = 68 m."},{"id":"10th-ch2-033-card","topic":"Echo","prompt":"Assume a separate echo requires at least 0.10 s delay. At sound speed 340 m/s, what is the minimum distance to a reflecting wall?","answer":"17 m","explanation":"The round-trip path must be at least 340 × 0.10 = 34 m, so the wall must be at least 17 m away."},{"id":"10th-ch2-034-card","topic":"Intensity","prompt":"A sound source transfers 0.60 W through an area of 3.0 m² normal to propagation. What is the intensity?","answer":"0.20 W/m²","explanation":"I = P/A = 0.60/3.0 = 0.20 W/m²."},{"id":"10th-ch2-035-card","topic":"Pitch and waveforms","prompt":"Two oscilloscope traces have the same time scale. Trace A shows 8 cycles and B shows 4 cycles in the same interval. Which sound has the higher pitch?","answer":"A, because its frequency is higher","explanation":"A completes twice as many cycles per unit time, so its frequency and pitch are higher."},{"id":"10th-ch2-036-card","topic":"Quality of sound","prompt":"Two sounds have the same frequency and amplitude but different waveforms. Which characteristic differs?","answer":"Quality or timbre","explanation":"Waveform differences at the same frequency and amplitude indicate different quality or timbre."},{"id":"10th-ch2-037-card","topic":"Audible range","prompt":"Which pair consists of one infrasonic and one ultrasonic frequency, respectively?","answer":"15 Hz and 25,000 Hz","explanation":"15 Hz is below 20 Hz and 25,000 Hz is above 20,000 Hz, so the pair is infrasonic then ultrasonic."},{"id":"10th-ch2-038-card","topic":"SONAR","prompt":"Sound travels in water at 1,500 m/s. A SONAR pulse returns from the seabed after 0.20 s. What is the water depth?","answer":"150 m","explanation":"Depth = vt/2 = 1,500 × 0.20 / 2 = 150 m. The pulse makes a round trip."},{"id":"10th-ch2-039-card","topic":"Medical ultrasound","prompt":"An ultrasonic pulse in soft tissue has speed 1,540 m/s. It returns from a boundary after 0.00010 s. How deep is the boundary?","answer":"0.077 m","explanation":"Depth = vt/2 = 1,540 × 0.00010 / 2 = 0.077 m, or 7.7 cm."},{"id":"10th-ch2-040-card","topic":"Industrial ultrasound","prompt":"An ultrasound detector receives an unexpected early reflected pulse from inside a metal block. What can this indicate?","answer":"An internal crack or flaw","explanation":"An internal defect can reflect ultrasound before the far surface does, allowing the defect to be located."},{"id":"10th-ch2-041-card","topic":"Industrial ultrasound","prompt":"In ultrasonic cleaning, why can dirt be removed from small inaccessible spaces?","answer":"Ultrasonic vibrations in the cleaning liquid help detach dirt","explanation":"Ultrasound produces rapid mechanical action in the cleaning liquid that loosens contaminants, including in small spaces."},{"id":"10th-ch2-042-card","topic":"Medical ultrasound","prompt":"Which technique uses reflected ultrasound to form images of the heart and its valves?","answer":"Echocardiography","explanation":"Echocardiography uses echoes of ultrasonic pulses to produce images of heart structures."},{"id":"10th-ch2-043-card","topic":"Measuring sound speed","prompt":"A distant flash is seen before its associated sound is heard. What is the main reason?","answer":"Light travels much faster than sound in air","explanation":"The travel time of light is negligible compared with sound over ordinary distances, so the flash is seen first."},{"id":"10th-ch2-044-card","topic":"Measuring sound speed","prompt":"During a direct sound-speed measurement, why is a relatively large separation between source and observer useful?","answer":"It makes the sound travel time easier to measure","explanation":"A longer path increases the travel time, reducing the relative effect of timing uncertainty. Distance and time are still both required."},{"id":"10th-ch2-045-card","topic":"Ultrasound and wavelength","prompt":"A bat emits sound of wavelength 0.0085 m in air where its speed is 340 m/s. How is the sound classified?","answer":"Ultrasonic, at 40,000 Hz","explanation":"f = v/λ = 340/0.0085 = 40,000 Hz. This exceeds 20,000 Hz, so it is ultrasound."},{"id":"10th-ch2-046-card","topic":"Sound speed and echo","prompt":"A sound wave has frequency 680 Hz and wavelength 0.50 m. Its echo returns after 0.60 s. How far away is the reflecting wall?","answer":"102 m","explanation":"First v = fλ = 680 × 0.50 = 340 m/s. Then d = vt/2 = 340 × 0.60 / 2 = 102 m."},{"id":"10th-ch2-047-card","topic":"Measuring sound speed","prompt":"A person is 85 m from a wall. The total time for 20 complete sound round trips between person and wall is 10 s. What sound speed is measured?","answer":"340 m/s","explanation":"Each round trip covers 2 × 85 = 170 m. Total path = 20 × 170 = 3,400 m. Speed = 3,400/10 = 340 m/s."},{"id":"10th-ch2-048-card","topic":"SONAR","prompt":"A ship measures the water depth at two positions using SONAR. The seabed echo returns after 0.12 s at the first position and 0.20 s at the second. Sound speed in water is 1,500 m/s. How much greater is the second depth?","answer":"60 m","explanation":"First depth = 1,500 × 0.12 / 2 = 90 m. Second depth = 1,500 × 0.20 / 2 = 150 m. The second depth is 150 − 90 = 60 m greater."},{"id":"10th-ch2-049-card","topic":"Temperature and sound speed","prompt":"In the same gas, use v₂/v₁ = √(T₂/T₁), with absolute temperatures. If sound speed is 330 m/s at 273 K, what is it at 1,092 K?","answer":"660 m/s","explanation":"T₂/T₁ = 1,092/273 = 4. Thus v₂/v₁ = √4 = 2 and v₂ = 660 m/s. Temperatures must be in kelvin."},{"id":"10th-ch2-050-card","topic":"Medical ultrasound and wavelength","prompt":"An ultrasonic pulse travels through tissue at 1,500 m/s with frequency 3.0 MHz. What is its wavelength?","answer":"0.50 mm","explanation":"3.0 MHz = 3,000,000 Hz. λ = 1,500/3,000,000 = 0.00050 m = 0.50 mm."}],"topics":[{"id":"Production of sound","name":"Production of sound"},{"id":"Nature of sound","name":"Nature of sound"},{"id":"Compressions and rarefactions","name":"Compressions and rarefactions"},{"id":"Medium","name":"Medium"},{"id":"Wavelength","name":"Wavelength"},{"id":"Sound speed","name":"Sound speed"},{"id":"Frequency","name":"Frequency"},{"id":"Temperature and humidity","name":"Temperature and humidity"},{"id":"Pitch","name":"Pitch"},{"id":"Loudness","name":"Loudness"},{"id":"Quality of sound","name":"Quality of sound"},{"id":"Intensity","name":"Intensity"},{"id":"Noise","name":"Noise"},{"id":"Noise control","name":"Noise control"},{"id":"Echo","name":"Echo"},{"id":"Audible range","name":"Audible range"},{"id":"Ultrasound","name":"Ultrasound"},{"id":"Measuring sound speed","name":"Measuring sound speed"},{"id":"Pitch and waveforms","name":"Pitch and waveforms"},{"id":"SONAR","name":"SONAR"},{"id":"Medical ultrasound","name":"Medical ultrasound"},{"id":"Industrial ultrasound","name":"Industrial ultrasound"},{"id":"Ultrasound and wavelength","name":"Ultrasound and wavelength"},{"id":"Sound speed and echo","name":"Sound speed and echo"},{"id":"Temperature and sound speed","name":"Temperature and sound speed"},{"id":"Medical ultrasound and wavelength","name":"Medical ultrasound and wavelength"}]},"11":{"title":"Kinematics","chapter":2,"mcqs":[{"id":"v01","type":"mcq","topic":"vectors","prompt":"Which quantity is a vector?","options":["Mass","Time","Displacement","Temperature"],"correct":2,"answer":"Displacement","explanation":"Displacement requires magnitude and direction. The other quantities listed are scalars.","difficulty":"Concept"},{"id":"v02","type":"mcq","topic":"vectors","prompt":"At a scale of 1 cm = 3 N, what arrow length represents a 12 N force?","options":["3 cm","4 cm","9 cm","36 cm"],"correct":1,"answer":"4 cm","explanation":"Length = 12 N ÷ (3 N/cm) = 4 cm. The arrow direction must also match the force.","difficulty":"Calculation"},{"id":"v03","type":"mcq","topic":"vectors","prompt":"Two vectors drawn at different positions are equal when they have the same…","options":["Magnitude only","Direction only","Magnitude and direction","Starting point"],"correct":2,"answer":"Magnitude and direction","explanation":"Equal vectors have the same magnitude and direction. Their drawn starting points need not coincide.","difficulty":"Concept"},{"id":"v04","type":"mcq","topic":"vectors","prompt":"What is the magnitude of a unit vector?","options":["0","1","Its original vector’s magnitude","It depends on direction"],"correct":1,"answer":"1","explanation":"A unit vector has magnitude one and indicates direction. It has no physical unit.","difficulty":"Concept"},{"id":"v05","type":"mcq","topic":"vectors","prompt":"A = 3i + 4j. Which is the unit vector along A?","options":["3i + 4j","0.6i + 0.8j","0.8i + 0.6j","5i + 5j"],"correct":1,"answer":"0.6i + 0.8j","explanation":"|A| = √(3²+4²) = 5. Divide both components by 5 to obtain 0.6i + 0.8j.","difficulty":"Calculation"},{"id":"v06","type":"mcq","topic":"vectors","prompt":"Which statement about −A is correct for a nonzero vector A?","options":["It has negative magnitude","It is perpendicular to A","It has equal magnitude and opposite direction","It is always zero"],"correct":2,"answer":"It has equal magnitude and opposite direction","explanation":"The minus sign reverses direction. Magnitudes remain nonnegative and equal.","difficulty":"Concept"},{"id":"v07","type":"mcq","topic":"vectors","prompt":"What is A + (−A)?","options":["A","2A","A unit vector","The zero vector"],"correct":3,"answer":"The zero vector","explanation":"The vectors cancel component by component, leaving zero magnitude and no unique direction.","difficulty":"Concept"},{"id":"v08","type":"mcq","topic":"vectors","prompt":"A point is at (2, −3, 6) m. What is the magnitude of its position vector?","options":["5 m","7 m","11 m","49 m"],"correct":1,"answer":"7 m","explanation":"|r| = √(2² + (−3)² + 6²) = √49 = 7 m.","difficulty":"Calculation"},{"id":"v09","type":"mcq","topic":"vectors","prompt":"Which vector may be translated without changing its magnitude or direction?","options":["Free vector","Only the zero vector","Only a position vector","Only a force at a fixed application point"],"correct":0,"answer":"Free vector","explanation":"A free vector can be moved parallel to itself. A position vector, in contrast, specifies a point relative to a chosen origin.","difficulty":"Concept"},{"id":"v10","type":"mcq","topic":"vectors","prompt":"Which statement correctly describes the Cartesian axes in three dimensions?","options":["All are parallel","Only x and y are perpendicular","They are mutually perpendicular and meet at an origin","They must point in the same direction"],"correct":2,"answer":"They are mutually perpendicular and meet at an origin","explanation":"The x, y, and z axes are mutually perpendicular and share an origin.","difficulty":"Concept"},{"id":"a01","type":"mcq","topic":"components","prompt":"Two perpendicular vectors have magnitudes 6 N and 8 N. Their resultant magnitude is…","options":["2 N","10 N","14 N","48 N"],"correct":1,"answer":"10 N","explanation":"For perpendicular vectors, R = √(6²+8²) = 10 N. Adding magnitudes would only apply if they pointed the same way.","difficulty":"Calculation"},{"id":"a02","type":"mcq","topic":"components","prompt":"Two forces of 5 N each act in opposite directions. Their resultant is…","options":["0 N","5 N","10 N","25 N"],"correct":0,"answer":"0 N","explanation":"Equal and opposite vectors cancel, so their resultant is the zero vector.","difficulty":"Concept"},{"id":"a03","type":"mcq","topic":"components","prompt":"A 10 N vector makes 60° with +x. What is its x component?","options":["5 N","5√3 N","10 N","20 N"],"correct":0,"answer":"5 N","explanation":"Ax = A cos θ = 10 cos 60° = 5 N. The angle is measured from +x.","difficulty":"Calculation"},{"id":"a04","type":"mcq","topic":"components","prompt":"A 10 N vector makes 30° with +x. What is its y component?","options":["10 N","5√3 N","5 N","0 N"],"correct":2,"answer":"5 N","explanation":"Ay = A sin θ = 10 sin 30° = 5 N.","difficulty":"Calculation"},{"id":"a05","type":"mcq","topic":"components","prompt":"A = 3i − 2j and B = −i + 5j. What is A + B?","options":["2i + 3j","4i − 7j","−3i − 10j","2i − 7j"],"correct":0,"answer":"2i + 3j","explanation":"Add corresponding components: (3−1)i + (−2+5)j = 2i + 3j.","difficulty":"Calculation"},{"id":"a06","type":"mcq","topic":"components","prompt":"For a vector with Rx < 0 and Ry > 0, the direction lies in…","options":["Quadrant I","Quadrant II","Quadrant III","Quadrant IV"],"correct":1,"answer":"Quadrant II","explanation":"Negative x and positive y place the vector in quadrant II. A simple inverse tangent must be corrected for the quadrant.","difficulty":"Concept"},{"id":"a07","type":"mcq","topic":"components","prompt":"Multiplying a nonzero vector by −2…","options":["Doubles magnitude and reverses direction","Halves magnitude","Doubles magnitude without changing direction","Makes magnitude negative"],"correct":0,"answer":"Doubles magnitude and reverses direction","explanation":"The factor’s absolute value scales magnitude by 2, and its negative sign reverses direction.","difficulty":"Concept"},{"id":"a08","type":"mcq","topic":"components","prompt":"Which equation expresses the commutative law of vector addition?","options":["A + B = B + A","A × B = B × A","A − B = B − A","A · A = 0"],"correct":0,"answer":"A + B = B + A","explanation":"Changing the order of vector addition does not change the resultant. Cross products and subtraction are generally not commutative.","difficulty":"Concept"},{"id":"a09","type":"mcq","topic":"components","prompt":"Vectors of magnitudes 3 and 7 can have a resultant magnitude in which interval?","options":["0 to 10","3 to 7","4 to 10","7 to 21"],"correct":2,"answer":"4 to 10","explanation":"The minimum is |7−3| = 4; the maximum is 7+3 = 10. Intermediate angles give intermediate magnitudes.","difficulty":"Calculation"},{"id":"a10","type":"mcq","topic":"components","prompt":"Two 10 N vectors have a common-tail angle of 60°. What is the resultant magnitude?","options":["10 N","10√2 N","10√3 N","20 N"],"correct":2,"answer":"10√3 N","explanation":"R² = 10²+10²+2(10)(10)cos60° = 300, so R = 10√3 N.","difficulty":"Calculation"},{"id":"p01","type":"mcq","topic":"products","prompt":"The dot product of two vectors is a…","options":["Vector parallel to A","Scalar","Vector perpendicular to both","Unit vector"],"correct":1,"answer":"Scalar","explanation":"The dot product A·B = AB cosθ has magnitude and sign, but no spatial direction.","difficulty":"Concept"},{"id":"p02","type":"mcq","topic":"products","prompt":"For two nonzero perpendicular vectors, A·B equals…","options":["AB","−AB","0","1"],"correct":2,"answer":"0","explanation":"A·B = AB cos90° = 0.","difficulty":"Concept"},{"id":"p03","type":"mcq","topic":"products","prompt":"For A = 2i + 3j − k and B = i − 2j + 4k, A·B is…","options":["−8","0","8","12"],"correct":0,"answer":"−8","explanation":"Multiply corresponding components and sum: 2(1)+3(−2)+(−1)(4)=−8.","difficulty":"Calculation"},{"id":"p04","type":"mcq","topic":"products","prompt":"What is i × j in a right-handed Cartesian system?","options":["i","j","k","−k"],"correct":2,"answer":"k","explanation":"The cyclic order i→j→k gives i×j=k. Reversing the order would give −k.","difficulty":"Concept"},{"id":"p05","type":"mcq","topic":"products","prompt":"For fixed nonzero A and B, |A×B| is maximum when θ is…","options":["0°","45°","90°","180°"],"correct":2,"answer":"90°","explanation":"|A×B| = AB sinθ. Sine reaches its maximum value 1 at 90°.","difficulty":"Concept"},{"id":"p06","type":"mcq","topic":"products","prompt":"Which cross-product identity is correct?","options":["A×B = B×A","A×B = −(B×A)","A×A = A²","A×B is always a scalar"],"correct":1,"answer":"A×B = −(B×A)","explanation":"Reversing the order reverses the direction of the cross product; it is anticommutative.","difficulty":"Concept"},{"id":"p07","type":"mcq","topic":"products","prompt":"A constant 10 N force acts at 60° to a displacement of 2 m. What work does it do?","options":["0 J","10 J","20 J","40 J"],"correct":1,"answer":"10 J","explanation":"W = Fs cosθ = 10×2×cos60° = 10 J. Only the force component along displacement contributes.","difficulty":"Calculation"},{"id":"p08","type":"mcq","topic":"products","prompt":"A 5 N force is perpendicular to a 2 m lever arm. What is the torque magnitude?","options":["2.5 N m","5 N m","7 N m","10 N m"],"correct":3,"answer":"10 N m","explanation":"|τ| = rF sin90° = 2×5 = 10 N m. Torque is a cross-product application.","difficulty":"Calculation"},{"id":"p09","type":"mcq","topic":"products","prompt":"What is the angle between nonzero vectors if their dot product is negative?","options":["Always 0°","Acute","Greater than 90° and at most 180°","Always 90°"],"correct":2,"answer":"Greater than 90° and at most 180°","explanation":"A negative dot product means cosθ<0, so 90°<θ≤180°.","difficulty":"Concept"},{"id":"p10","type":"mcq","topic":"products","prompt":"The magnitude |A×B| geometrically represents the area of…","options":["The parallelogram spanned by A and B","Only half that parallelogram","A sphere of radius A","A circle of radius B"],"correct":0,"answer":"The parallelogram spanned by A and B","explanation":"A parallelogram has base A and perpendicular height B sinθ, giving area AB sinθ.","difficulty":"Concept"},{"id":"m01","type":"mcq","topic":"motion","prompt":"A student walks 8 m east then 3 m west. What are distance and displacement magnitude?","options":["5 m and 11 m","11 m and 5 m","11 m and 11 m","5 m and 5 m"],"correct":1,"answer":"11 m and 5 m","explanation":"Distance adds path lengths: 8+3=11 m. Displacement is 8−3=5 m east.","difficulty":"Calculation"},{"id":"m02","type":"mcq","topic":"motion","prompt":"For a completed round trip, which statement must be true?","options":["Distance is zero","Average speed is zero","Displacement is zero","Acceleration is always zero"],"correct":2,"answer":"Displacement is zero","explanation":"Final and initial positions coincide, so displacement is zero. A nontrivial trip has positive distance.","difficulty":"Concept"},{"id":"m03","type":"mcq","topic":"motion","prompt":"Average speed is defined as…","options":["Displacement divided by time","Total distance divided by total elapsed time","Always (initial speed + final speed)/2","Change in velocity divided by time"],"correct":1,"answer":"Total distance divided by total elapsed time","explanation":"Total distance divided by total time is the general definition. The arithmetic mean is valid only in suitable special cases.","difficulty":"Concept"},{"id":"m04","type":"mcq","topic":"motion","prompt":"Equal distances are travelled at 10 m/s and 20 m/s. What is the average speed?","options":["10 m/s","13.33 m/s","15 m/s","20 m/s"],"correct":1,"answer":"13.33 m/s","explanation":"For 100 m each, the times are 10 s and 5 s. Total speed average is 200/15 ≈13.33 m/s.","difficulty":"Calculation"},{"id":"m05","type":"mcq","topic":"motion","prompt":"An object has constant speed but its direction changes. Which statement is correct?","options":["Its velocity is constant","Its acceleration must be zero","Its velocity changes","Its displacement must be zero"],"correct":2,"answer":"Its velocity changes","explanation":"Velocity includes direction. Changing direction changes velocity and therefore involves acceleration.","difficulty":"Concept"},{"id":"m06","type":"mcq","topic":"motion","prompt":"An object has v = −8 m/s and a = −2 m/s². Its speed is…","options":["Increasing","Decreasing","Necessarily zero","Constant"],"correct":0,"answer":"Increasing","explanation":"Velocity and acceleration have the same sign, so the magnitude of velocity increases. Negative acceleration alone does not mean slowing.","difficulty":"Concept"},{"id":"m07","type":"mcq","topic":"motion","prompt":"The SI unit of acceleration is…","options":["m","m/s","m/s²","m²/s"],"correct":2,"answer":"m/s²","explanation":"Acceleration is change of velocity per unit time: (m/s)/s = m/s².","difficulty":"Concept"},{"id":"m08","type":"mcq","topic":"motion","prompt":"Velocity changes from 4 m/s to 10 m/s in 3 s along the same positive axis. Average acceleration is…","options":["2 m/s²","3 m/s²","4.67 m/s²","18 m/s²"],"correct":0,"answer":"2 m/s²","explanation":"aavg = (10−4)/3 = 2 m/s².","difficulty":"Calculation"},{"id":"m09","type":"mcq","topic":"motion","prompt":"Two vehicles move east at 15 m/s and 10 m/s. The faster vehicle’s velocity relative to the slower one is…","options":["25 m/s east","5 m/s east","5 m/s west","0 m/s"],"correct":1,"answer":"5 m/s east","explanation":"vA/B = vA−vB = 15−10=5 m/s east.","difficulty":"Calculation"},{"id":"m10","type":"mcq","topic":"motion","prompt":"Instantaneous velocity is directed…","options":["Always toward the origin","Along the tangent to the path","Always vertically upward","Always perpendicular to motion"],"correct":1,"answer":"Along the tangent to the path","explanation":"Instantaneous velocity follows the tangent to the trajectory. Its magnitude is instantaneous speed.","difficulty":"Concept"},{"id":"g01","type":"mcq","topic":"graphs","prompt":"The slope of a displacement–time graph gives…","options":["Acceleration","Velocity","Distance","Force"],"correct":1,"answer":"Velocity","explanation":"The slope is change in displacement divided by time, which is velocity. A tangent gives instantaneous velocity.","difficulty":"Concept"},{"id":"g02","type":"mcq","topic":"graphs","prompt":"A horizontal displacement–time line represents…","options":["Rest","Constant nonzero velocity","Constant positive acceleration","Increasing speed"],"correct":0,"answer":"Rest","explanation":"Displacement is unchanged, so velocity is zero.","difficulty":"Concept"},{"id":"g03","type":"mcq","topic":"graphs","prompt":"The signed area under a velocity–time graph gives…","options":["Acceleration","Displacement","Always distance","Change in acceleration"],"correct":1,"answer":"Displacement","explanation":"Velocity multiplied by time has units of displacement. Below-axis areas count negatively.","difficulty":"Concept"},{"id":"g04","type":"mcq","topic":"graphs","prompt":"Velocity rises linearly from 0 to 8 m/s in 4 s. What is the displacement?","options":["8 m","16 m","24 m","32 m"],"correct":1,"answer":"16 m","explanation":"The area is a triangle: ½×4×8=16 m.","difficulty":"Calculation"},{"id":"g05","type":"mcq","topic":"graphs","prompt":"A body moves at +3 m/s for 2 s, then −3 m/s for 2 s. Distance and displacement are…","options":["0 m and 12 m","12 m and 0 m","6 m and 6 m","12 m and 12 m"],"correct":1,"answer":"12 m and 0 m","explanation":"Signed areas are +6 m and −6 m, giving zero displacement. Add magnitudes for distance: 12 m.","difficulty":"Calculation"},{"id":"g06","type":"mcq","topic":"graphs","prompt":"A body starts from rest with constant acceleration 3 m/s² for 4 s. Final velocity is…","options":["7 m/s","12 m/s","24 m/s","48 m/s"],"correct":1,"answer":"12 m/s","explanation":"v=u+at=0+3×4=12 m/s.","difficulty":"Calculation"},{"id":"g07","type":"mcq","topic":"graphs","prompt":"A body starts from rest with constant acceleration 3 m/s² for 4 s. Displacement is…","options":["6 m","12 m","24 m","48 m"],"correct":2,"answer":"24 m","explanation":"s=ut+½at²=0+½×3×16=24 m.","difficulty":"Calculation"},{"id":"g08","type":"mcq","topic":"graphs","prompt":"A car slows uniformly from 20 m/s to rest with a = −5 m/s². Stopping distance is…","options":["4 m","20 m","40 m","80 m"],"correct":2,"answer":"40 m","explanation":"v²=u²+2as gives 0=400−10s, so s=40 m.","difficulty":"Calculation"},{"id":"g09","type":"mcq","topic":"graphs","prompt":"Which condition is required for v = u + at with a single constant value of a over an interval?","options":["Zero initial velocity","Constant acceleration over that interval","Zero displacement","Motion lasting exactly one second"],"correct":1,"answer":"Constant acceleration over that interval","explanation":"The familiar constant-acceleration equations use a fixed acceleration for the interval. Initial velocity need not be zero.","difficulty":"Concept"},{"id":"g10","type":"mcq","topic":"graphs","prompt":"From rest with a = 2 m/s², what is displacement during the fifth second?","options":["5 m","9 m","10 m","25 m"],"correct":1,"answer":"9 m","explanation":"s(5)−s(4)=½×2×(25−16)=9 m. Total displacement in five seconds would be 25 m.","difficulty":"Calculation"},{"id":"f01","type":"mcq","topic":"projectiles","prompt":"At the highest point of an ideal projectile’s path, its acceleration is…","options":["Zero","g upward","g downward","Horizontal"],"correct":2,"answer":"g downward","explanation":"Gravity continues to act. Only the vertical velocity component is zero at the top.","difficulty":"Concept"},{"id":"f02","type":"mcq","topic":"projectiles","prompt":"Ignoring air resistance, a projectile’s horizontal velocity is…","options":["Constant","Constantly increasing","Zero at the top","Equal to gt"],"correct":0,"answer":"Constant","explanation":"There is no horizontal acceleration in the ideal model, so vx=u cosθ remains constant.","difficulty":"Concept"},{"id":"f03","type":"mcq","topic":"projectiles","prompt":"For fixed launch speed and equal launch/landing heights, maximum range occurs at…","options":["30°","45°","60°","90°"],"correct":1,"answer":"45°","explanation":"R=u²sin2θ/g. The maximum sin2θ is 1, giving 2θ=90° and θ=45°.","difficulty":"Concept"},{"id":"f04","type":"mcq","topic":"projectiles","prompt":"Two projectiles have equal launch speeds and land at launch height. Angles 30° and 60° give…","options":["Equal flight times","Equal maximum heights","Equal ranges","Zero ranges"],"correct":2,"answer":"Equal ranges","explanation":"They are complementary angles, so sin60°=sin120° gives equal ranges. The 60° launch stays aloft longer and rises higher.","difficulty":"Concept"},{"id":"f05","type":"mcq","topic":"projectiles","prompt":"A projectile is launched at 20 m/s and 30°. Use g = 10 m/s² and equal launch/landing heights. Flight time is…","options":["1 s","2 s","4 s","5 s"],"correct":1,"answer":"2 s","explanation":"T=2u sinθ/g=2×20×0.5/10=2 s.","difficulty":"Calculation"},{"id":"f06","type":"mcq","topic":"projectiles","prompt":"For u = 20 m/s, θ = 30°, and g = 10 m/s², the maximum rise is…","options":["5 m","10 m","20 m","40 m"],"correct":0,"answer":"5 m","explanation":"H=u²sin²θ/(2g)=400×0.25/20=5 m.","difficulty":"Calculation"},{"id":"f07","type":"mcq","topic":"projectiles","prompt":"A body is launched horizontally at 12 m/s from 20 m above ground. Use g = 10 m/s². Horizontal distance before impact is…","options":["12 m","20 m","24 m","40 m"],"correct":2,"answer":"24 m","explanation":"Vertical motion gives 20=½×10×t², so t=2 s. Horizontal distance=12×2=24 m.","difficulty":"Calculation"},{"id":"f08","type":"mcq","topic":"projectiles","prompt":"Which formula must generally be replaced by a vertical-position calculation when landing height differs from launch height?","options":["vx = u cosθ","ax = 0","T = 2u sinθ/g","ay = −g"],"correct":2,"answer":"T = 2u sinθ/g","explanation":"The symmetric flight-time formula assumes equal launch and landing heights. Solve y−y0=u sinθ t−½gt² for the appropriate positive time instead.","difficulty":"Concept"},{"id":"f09","type":"mcq","topic":"projectiles","prompt":"A package is released from a helicopter ascending at 12 m/s. Immediately after release, its ground-frame vertical velocity is…","options":["0 m/s","12 m/s upward","12 m/s downward","9.8 m/s downward"],"correct":1,"answer":"12 m/s upward","explanation":"The package initially retains the helicopter’s velocity. Releasing it does not instantly cancel its upward motion.","difficulty":"Concept"},{"id":"f10","type":"mcq","topic":"projectiles","prompt":"If an ideal projectile’s speed doubles at the same launch angle and equal landing height, its range becomes…","options":["Half as large","Twice as large","Four times as large","Unchanged"],"correct":2,"answer":"Four times as large","explanation":"R is proportional to u² at fixed θ and g. Doubling u multiplies range by 4.","difficulty":"Concept"}],"cards":[{"id":"vc1","type":"card","topic":"vectors","prompt":"Explain the difference between a scalar and a vector, with two examples of each.","answer":"Scalars need magnitude; vectors need magnitude and direction.","explanation":"Mass and speed are scalars. Displacement and velocity are vectors. Vector quantities follow vector addition, so direction affects their resultant.","difficulty":"Recall"},{"id":"vc2","type":"card","topic":"vectors","prompt":"How do you represent a physical vector with an arrow?","answer":"Use length for magnitude and an arrowhead for direction.","explanation":"Choose a scale, such as 1 cm = 2 N. A 6 N force east becomes a 3 cm arrow east. Its tail is the initial end and its head the terminal end.","difficulty":"Recall"},{"id":"vc3","type":"card","topic":"vectors","prompt":"Define a unit vector and obtain one along 6i + 8j.","answer":"A unit vector has magnitude 1; here it is 0.6i + 0.8j.","explanation":"The original magnitude is √(36+64)=10. Divide each component by 10. A zero vector cannot be normalized because its magnitude is zero.","difficulty":"Calculation"},{"id":"vc4","type":"card","topic":"vectors","prompt":"Distinguish a position vector, a free vector, and a zero vector.","answer":"Position locates a point from an origin; free vectors can be translated; zero vectors have zero magnitude.","explanation":"A position vector r = xi + yj + zk specifies a point in a chosen frame. Translating a free vector does not change it. The zero vector has no unique direction.","difficulty":"Recall"},{"id":"vb1","type":"blank","topic":"vectors","prompt":"A vector whose magnitude is one is called a ____ vector.","answer":"unit","explanation":"Unit vectors indicate a direction and have magnitude 1.","kind":"text","aliases":["unit"],"unit":"","tolerance":0.01,"difficulty":"Recall"},{"id":"vb2","type":"blank","topic":"vectors","prompt":"Find |r| for r = 2i + 3j + 6k metres.","answer":"7 m","explanation":"|r| = √(2²+3²+6²) = √49 = 7 m.","kind":"number","value":7,"unit":"m","tolerance":0.01,"difficulty":"Calculation"},{"id":"ac1","type":"card","topic":"components","prompt":"Describe the head-to-tail method of adding vectors.","answer":"Connect each new tail to the previous head; join the first tail to the last head.","explanation":"The joining vector is the resultant. Vectors may be translated parallel to themselves for this construction without changing their magnitudes or directions.","difficulty":"Recall"},{"id":"ac2","type":"card","topic":"components","prompt":"How do you subtract B from A?","answer":"Add the negative vector: A − B = A + (−B).","explanation":"Reverse B without changing its magnitude, then use head-to-tail addition. Subtracting just the magnitudes ignores the directions.","difficulty":"Recall"},{"id":"ac3","type":"card","topic":"components","prompt":"Find the magnitude and direction of R = −3i + 3j N.","answer":"3√2 N, at 135° anticlockwise from +x.","explanation":"Magnitude is √(9+9)=3√2. Since x<0 and y>0, R is in quadrant II. The reference angle is 45°, giving 180°−45°=135°.","difficulty":"Calculation"},{"id":"ac4","type":"card","topic":"components","prompt":"Explain the rectangular-component method of adding any number of vectors.","answer":"Resolve, sum x and y components separately, then reconstruct the resultant.","explanation":"With angles from +x, Ax=A cosθ and Ay=A sinθ. Rx=ΣAx and Ry=ΣAy. Then R=√(Rx²+Ry²); determine the direction with quadrant awareness.","difficulty":"Recall"},{"id":"ab1","type":"blank","topic":"components","prompt":"Find the x component of a 20 N vector at 60° above +x.","answer":"10 N","explanation":"Ax = 20 cos60° = 10 N.","kind":"number","value":10,"unit":"N","tolerance":0.01,"difficulty":"Calculation"},{"id":"ab2","type":"blank","topic":"components","prompt":"A resultant has perpendicular components 9 m and 12 m. Find its magnitude.","answer":"15 m","explanation":"R = √(9²+12²) = √225 = 15 m.","kind":"number","value":15,"unit":"m","tolerance":0.01,"difficulty":"Calculation"},{"id":"pc1","type":"card","topic":"products","prompt":"State the dot product in magnitude-angle and component forms.","answer":"A·B = AB cosθ = AxBx + AyBy + AzBz.","explanation":"It is a scalar and is commutative. Mixed Cartesian unit-vector dot products vanish; each unit vector dotted with itself equals 1.","difficulty":"Recall"},{"id":"pc2","type":"card","topic":"products","prompt":"Explain the right-hand rule for A×B and what reversing the order does.","answer":"Curl fingers from A toward B; the thumb gives A×B. Reversing order reverses its direction.","explanation":"The cross product is perpendicular to the plane of A and B. B×A=−(A×B), while their magnitudes are equal.","difficulty":"Recall"},{"id":"pc3","type":"card","topic":"products","prompt":"Compare dot and cross products when two nonzero vectors are parallel, perpendicular, or antiparallel.","answer":"Dot: +AB, 0, −AB. Cross magnitude: 0, AB, 0.","explanation":"Use cosθ for the dot product and sinθ for cross-product magnitude at 0°, 90°, and 180°. A×A is zero, while A·A=A².","difficulty":"Recall"},{"id":"pc4","type":"card","topic":"products","prompt":"Find (2i + j) × (i + 3j).","answer":"5k","explanation":"Only the k component remains: AxBy−AyBx = 2×3−1×1 = 5. Thus the result is 5k, perpendicular to the xy plane.","difficulty":"Calculation"},{"id":"pb1","type":"blank","topic":"products","prompt":"Complete the right-handed unit-vector relation: j × k = ____.","answer":"i","explanation":"The cyclic relations are i×j=k, j×k=i, and k×i=j. Enter i.","kind":"text","aliases":["i"],"unit":"","tolerance":0.01,"difficulty":"Recall"},{"id":"pb2","type":"blank","topic":"products","prompt":"Vectors of magnitudes 4 and 5 are perpendicular. Find their cross-product magnitude.","answer":"20","explanation":"|A×B| = AB sin90° = 4×5 = 20.","kind":"number","value":20,"unit":"","tolerance":0.01,"difficulty":"Calculation"},{"id":"mc1","type":"card","topic":"motion","prompt":"Explain why distance can be positive while displacement is zero.","answer":"A round trip has positive path length but no net change of position.","explanation":"For 3 m east followed by 3 m west, distance is 6 m and displacement is zero. Over a nonzero time, average speed is positive and average velocity is zero.","difficulty":"Recall"},{"id":"mc2","type":"card","topic":"motion","prompt":"Distinguish average speed, average velocity, and instantaneous velocity.","answer":"Distance/time, displacement/time, and the limiting rate of change of position.","explanation":"Average quantities refer to a finite interval. Instantaneous velocity v=dr/dt is tangent to the path at a moment, and its magnitude is instantaneous speed.","difficulty":"Recall"},{"id":"mc3","type":"card","topic":"motion","prompt":"Does negative acceleration always mean that an object is slowing down?","answer":"No. Compare the directions of velocity and acceleration.","explanation":"In one dimension, equal signs mean increasing speed and opposite signs mean decreasing speed. For example v=−8 m/s and a=−2 m/s² describe speeding up in the negative direction.","difficulty":"Recall"},{"id":"mc4","type":"card","topic":"motion","prompt":"Can an object have zero initial velocity and nonzero acceleration? Give an example.","answer":"Yes: a body released from rest in free fall.","explanation":"At the instant of release u=0, while acceleration is downward with magnitude g. Zero velocity at an instant does not imply zero acceleration.","difficulty":"Recall"},{"id":"mb1","type":"blank","topic":"motion","prompt":"The rate of change of velocity with time is called ____.","answer":"acceleration","explanation":"Acceleration measures change in velocity, including changes in magnitude or direction.","kind":"text","aliases":["acceleration"],"unit":"","tolerance":0.01,"difficulty":"Recall"},{"id":"mb2","type":"blank","topic":"motion","prompt":"A body covers 150 m in 30 s. Find its average speed.","answer":"5 m/s","explanation":"Average speed = total distance / total time = 150/30=5 m/s.","kind":"number","value":5,"unit":"m/s","tolerance":0.01,"difficulty":"Calculation"},{"id":"gc1","type":"card","topic":"graphs","prompt":"Derive v = u + at from a velocity–time graph.","answer":"For a straight line, slope a = (v−u)/t, so v=u+at.","explanation":"The slope is constant acceleration. Multiply by t and add u. The same result follows from the definition of average acceleration when acceleration is uniform.","difficulty":"Derivation"},{"id":"gc2","type":"card","topic":"graphs","prompt":"Derive s = ut + ½at² using a velocity–time graph.","answer":"Displacement is rectangle area ut plus triangle area ½(v−u)t.","explanation":"Since v−u=at, the triangle area is ½at². Adding gives s=ut+½at². Areas are signed if velocity is negative.","difficulty":"Derivation"},{"id":"gc3","type":"card","topic":"graphs","prompt":"Derive v² = u² + 2as.","answer":"Combine s=½(u+v)t with t=(v−u)/a.","explanation":"For nonzero a, s=(u+v)(v−u)/(2a)=(v²−u²)/(2a). Rearranging gives v²=u²+2as. When a=0, v=u and the final identity still holds.","difficulty":"Derivation"},{"id":"gc4","type":"card","topic":"graphs","prompt":"Explain when area under velocity–time gives distance and when it gives displacement.","answer":"Signed area always gives displacement; add absolute areas for distance.","explanation":"If velocity keeps one sign, displacement magnitude equals distance. If it changes sign, sum the magnitudes of each positive and negative region for distance.","difficulty":"Recall"},{"id":"gb1","type":"blank","topic":"graphs","prompt":"From rest, a body accelerates at 2 m/s² for 5 s. Find its final velocity.","answer":"10 m/s","explanation":"v=u+at=0+2×5=10 m/s.","kind":"number","value":10,"unit":"m/s","tolerance":0.01,"difficulty":"Calculation"},{"id":"gb2","type":"blank","topic":"graphs","prompt":"A car slows from 12 m/s to rest with constant acceleration −3 m/s². Find the stopping time.","answer":"4 s","explanation":"0=12−3t, so t=4 s.","kind":"number","value":4,"unit":"s","tolerance":0.01,"difficulty":"Calculation"},{"id":"fc1","type":"card","topic":"projectiles","prompt":"Derive the time to the top and total time of flight for an equal-height projectile.","answer":"tup=u sinθ/g; T=2u sinθ/g.","explanation":"At the top, 0=u sinθ−gt gives tup. At launch height again, 0=(u sinθ)t−½gt²; taking the nonzero root gives T. These times differ by a factor of two only for equal-height launch and landing.","difficulty":"Derivation"},{"id":"fc2","type":"card","topic":"projectiles","prompt":"Derive maximum height and horizontal range for an equal-height projectile.","answer":"H=u²sin²θ/(2g); R=u²sin2θ/g.","explanation":"At the top, vy²=uy²−2gH with vy=0 gives H. Then R=vxT=(u cosθ)(2u sinθ/g); use 2sinθcosθ=sin2θ. H is measured above the launch point.","difficulty":"Derivation"},{"id":"fc3","type":"card","topic":"projectiles","prompt":"Why are horizontal and vertical projectile motions treated independently?","answer":"Their component equations have different accelerations but share the same time.","explanation":"Ignoring drag, ax=0 while ay=−g. A horizontal launch does not change vertical falling time for the same starting height and initial vertical velocity. Combine the two component positions at each time to obtain the trajectory.","difficulty":"Recall"},{"id":"fc4","type":"card","topic":"projectiles","prompt":"For a projectile landing at launch height, at what angle does its range equal its maximum height?","answer":"θ = arctan 4 ≈ 76°.","explanation":"R/H = [u²sin2θ/g]/[u²sin²θ/(2g)] = 4cotθ. Setting R/H=1 gives tanθ=4. This relation uses the equal-height range formula.","difficulty":"Calculation"},{"id":"fb1","type":"blank","topic":"projectiles","prompt":"A ball is thrown vertically upward at 20 m/s. Use g = 10 m/s². Find time to the highest point.","answer":"2 s","explanation":"At the top v=0. Thus 0=20−10t, so t=2 s.","kind":"number","value":2,"unit":"s","tolerance":0.01,"difficulty":"Calculation"},{"id":"fb2","type":"blank","topic":"projectiles","prompt":"For u = 10 m/s, θ = 45°, and g = 10 m/s², find range if landing is at launch height.","answer":"10 m","explanation":"R=u²sin2θ/g=100sin90°/10=10 m.","kind":"number","value":10,"unit":"m","tolerance":0.01,"difficulty":"Calculation"}],"topics":[{"id":"vectors","name":"Vectors & coordinates","pages":"31–35"},{"id":"components","name":"Addition & components","pages":"32–37"},{"id":"products","name":"Dot & cross products","pages":"38–41"},{"id":"motion","name":"Motion quantities","pages":"41–45, 53–54"},{"id":"graphs","name":"Graphs & equations","pages":"43–48"},{"id":"projectiles","name":"Free fall & projectiles","pages":"49–56"}]},"12":{"title":"First Law of Thermodynamics","chapter":2,"mcqs":[{"id":"h01","type":"mcq","topic":"heat","prompt":"Heat is energy transferred because of a difference in…","options":["Mass","Temperature","Volume only","Number of particles only"],"correct":1,"answer":"Temperature","explanation":"Heat transfers between a system and its surroundings because of a temperature difference. It is not the thermal energy stored in the body.","difficulty":"Recall","steps":["Heat transfers between a system and its surroundings because of a temperature difference. It is not the thermal energy stored in the body."]},{"id":"h02","type":"mcq","topic":"heat","prompt":"The SI unit used for both heat and work is…","options":["Kelvin","Pascal","Joule","Watt"],"correct":2,"answer":"Joule","explanation":"Heat and work are energy transfers. Their SI unit is the joule; the watt measures power.","difficulty":"Recall","steps":["Heat and work are energy transfers. Their SI unit is the joule; the watt measures power."]},{"id":"h03","type":"mcq","topic":"heat","prompt":"In ordinary spontaneous thermal contact, heat flows…","options":["From lower to higher temperature","From higher to lower temperature","Only between equal temperatures","Only from the larger body"],"correct":1,"answer":"From higher to lower temperature","explanation":"Heat transfer is from higher to lower temperature in spontaneous thermal contact. The relative sizes of the bodies do not set this direction.","difficulty":"Concept","steps":["Heat transfer is from higher to lower temperature in spontaneous thermal contact. The relative sizes of the bodies do not set this direction."]},{"id":"h04","type":"mcq","topic":"heat","prompt":"An open system can exchange with its surroundings…","options":["Neither matter nor energy","Energy but never matter","Matter but never energy","Both matter and energy"],"correct":3,"answer":"Both matter and energy","explanation":"An open system permits both matter and energy to cross its boundary, as with an uncovered hot drink losing vapour.","difficulty":"Recall","steps":["An open system permits both matter and energy to cross its boundary, as with an uncovered hot drink losing vapour."]},{"id":"h05","type":"mcq","topic":"heat","prompt":"Which statement correctly describes a closed system?","options":["It cannot exchange heat","It cannot exchange work","It exchanges energy but not matter","It exchanges matter but not energy"],"correct":2,"answer":"It exchanges energy but not matter","explanation":"A closed system keeps its matter but can exchange energy through heat or work. A sealed movable piston can therefore be a closed system.","difficulty":"Concept","steps":["A closed system keeps its matter but can exchange energy through heat or work. A sealed movable piston can therefore be a closed system."]},{"id":"h06","type":"mcq","topic":"heat","prompt":"An ideal isolated system exchanges…","options":["Heat only","Work only","Matter only","Neither matter nor energy"],"correct":3,"answer":"Neither matter nor energy","explanation":"An isolated system permits neither matter nor energy transfer across its boundary. Insulation alone is not enough if a movable boundary can do work.","difficulty":"Recall","steps":["An isolated system permits neither matter nor energy transfer across its boundary. Insulation alone is not enough if a movable boundary can do work."]},{"id":"h07","type":"mcq","topic":"heat","prompt":"The real or imaginary surface separating a system from its surroundings is called its…","options":["Boundary","Temperature","Internal energy","Heat capacity"],"correct":0,"answer":"Boundary","explanation":"The boundary defines what lies inside the chosen system and what lies outside. It can be real or imaginary.","difficulty":"Recall","steps":["The boundary defines what lies inside the chosen system and what lies outside. It can be real or imaginary."]},{"id":"h08","type":"mcq","topic":"heat","prompt":"Warming the hands by rubbing them mainly illustrates…","options":["Creation of energy","Conversion of mechanical work to internal energy","Heat flowing from cold to hot without work","Disappearance of internal energy"],"correct":1,"answer":"Conversion of mechanical work to internal energy","explanation":"Mechanical work against friction increases the microscopic energy of the hands. Energy is converted, not created.","difficulty":"Concept","steps":["Mechanical work against friction increases the microscopic energy of the hands. Energy is converted, not created."]},{"id":"h09","type":"mcq","topic":"heat","prompt":"An insulated gas cylinder has a movable piston and does work on its surroundings. It is…","options":["Necessarily isolated","Closed but not isolated, if no matter escapes","Open because its volume changes","At constant temperature by definition"],"correct":1,"answer":"Closed but not isolated, if no matter escapes","explanation":"No matter crosses, so it can be closed. Work does cross the boundary, so it is not isolated even though heat transfer is prevented.","difficulty":"Challenge","steps":["No matter crosses, so it can be closed. Work does cross the boundary, so it is not isolated even though heat transfer is prevented."]},{"id":"h10","type":"mcq","topic":"heat","prompt":"The word surroundings refers to…","options":["Only the gas molecules","Everything outside the chosen system","Only the boundary","Only bodies colder than the system"],"correct":1,"answer":"Everything outside the chosen system","explanation":"The surroundings are everything outside the chosen system. They can exchange energy or matter with it depending on the boundary.","difficulty":"Concept","steps":["The surroundings are everything outside the chosen system. They can exchange energy or matter with it depending on the boundary."]},{"id":"w01","type":"mcq","topic":"work","prompt":"For constant external pressure, work done by an expanding gas is…","options":["Pext(Vf − Vi)","Pext/(Vf − Vi)","(Vf − Vi)/Pext","Pext(Vi − Vf)"],"correct":0,"answer":"Pext(Vf − Vi)","explanation":"The piston force is Pext A and the volume change is A times its displacement, so W=PextΔV. Expansion gives positive work by the gas.","difficulty":"Concept","steps":["The piston force is Pext A and the volume change is A times its displacement, so W=PextΔV. Expansion gives positive work by the gas."]},{"id":"w02","type":"mcq","topic":"work","prompt":"Using W positive for work done by a gas, compression against a positive external pressure gives…","options":["W > 0","W < 0","W = 0 always","W independent of volume change"],"correct":1,"answer":"W < 0","explanation":"Compression has Vf<Vi, so ΔV<0 and W=PextΔV<0. Work done on the gas is positive.","difficulty":"Concept","steps":["Compression has Vf<Vi, so ΔV<0 and W=PextΔV<0. Work done on the gas is positive."]},{"id":"w03","type":"mcq","topic":"work","prompt":"A gas expands from 2 L to 5 L against a constant external pressure of 100 kPa. Work done by the gas is…","options":["30 J","200 J","300 J","500 J"],"correct":2,"answer":"300 J","explanation":"ΔV=3 L=0.003 m³. W=100000×0.003=300 J. Equivalently 100 kPa×3 L=300 J.","difficulty":"Calculation","steps":["ΔV = Vf − Vi = 5 − 2 = 3 L = 0.003 m³.","W = PextΔV = 100000 × 0.003 = 300 J. The sign is positive because the gas expands."]},{"id":"w04","type":"mcq","topic":"work","prompt":"One kilopascal litre is equal to…","options":["0.001 J","1 J","100 J","1000 J"],"correct":1,"answer":"1 J","explanation":"1 kPa L=(1000 Pa)(0.001 m³)=1 Pa m³=1 J.","difficulty":"Calculation","steps":["1 kPa L=(1000 Pa)(0.001 m³)=1 Pa m³=1 J."]},{"id":"w05","type":"mcq","topic":"work","prompt":"At constant external pressure 200 kPa, gas is compressed from 5 L to 2 L. Its work on the surroundings is…","options":["+600 J","−600 J","+1400 J","0 J"],"correct":1,"answer":"−600 J","explanation":"ΔV=2−5=−3 L. W=200×(−3)=−600 J. The surroundings do +600 J of work on the gas.","difficulty":"Calculation","steps":["ΔV = 2 − 5 = −3 L.","Wby = PextΔV = 200 kPa × (−3 L) = −600 J. Therefore Won = +600 J."]},{"id":"w06","type":"mcq","topic":"work","prompt":"The area under a quasistatic pressure–volume expansion curve represents…","options":["Heat capacity","Work done by the gas","Internal energy itself","Temperature"],"correct":1,"answer":"Work done by the gas","explanation":"For quasistatic expansion, W=∫P dV. The signed area under the PV curve therefore gives boundary work.","difficulty":"Concept","steps":["For quasistatic expansion, W=∫P dV. The signed area under the PV curve therefore gives boundary work."]},{"id":"w07","type":"mcq","topic":"work","prompt":"If a process is represented by a vertical line on a PV graph, its PV work is…","options":["Positive","Negative","Zero","Equal to its initial pressure"],"correct":2,"answer":"Zero","explanation":"A vertical line has constant volume, so dV=0 throughout and ∫P dV=0.","difficulty":"Concept","steps":["A vertical line has constant volume, so dV=0 throughout and ∫P dV=0."]},{"id":"w08","type":"mcq","topic":"work","prompt":"During quasistatic expansion from 1 L to 3 L, pressure falls linearly from 300 kPa to 100 kPa. Work is…","options":["200 J","400 J","600 J","800 J"],"correct":1,"answer":"400 J","explanation":"The PV area is a trapezium: W=½(300+100)(3−1)=400 J. The constant-initial-pressure result 600 J is incorrect.","difficulty":"Challenge","steps":["For a straight PV line, mean pressure = (300 + 100)/2 = 200 kPa.","ΔV = 3 − 1 = 2 L, so W = 200 × 2 = 400 J."]},{"id":"w09","type":"mcq","topic":"work","prompt":"A gas freely expands against a vacuum. Its external-pressure boundary work is…","options":["Positive because volume increases","Negative because pressure falls","Zero because external pressure is zero","Always equal to its internal energy"],"correct":2,"answer":"Zero because external pressure is zero","explanation":"W=∫Pext dV. In a vacuum Pext=0, so the gas does no external-pressure work despite increasing its volume.","difficulty":"Challenge","steps":["W=∫Pext dV. In a vacuum Pext=0, so the gas does no external-pressure work despite increasing its volume."]},{"id":"w10","type":"mcq","topic":"work","prompt":"A gas does 2 atm L of expansion work. Use 1 atm L = 101.325 J. This is approximately…","options":["2 J","101.3 J","202.7 J","2000 J"],"correct":2,"answer":"202.7 J","explanation":"2×101.325=202.65 J, which rounds to 202.7 J.","difficulty":"Calculation","steps":["2×101.325=202.65 J, which rounds to 202.7 J."]},{"id":"e01","type":"mcq","topic":"energy","prompt":"Internal energy consists of the system’s…","options":["Bulk translational kinetic energy only","Microscopic kinetic and potential energies","External gravitational energy only","Heat stored as a fluid"],"correct":1,"answer":"Microscopic kinetic and potential energies","explanation":"Internal energy refers to microscopic motion and interactions. It excludes the bulk motion of the whole sample.","difficulty":"Concept","steps":["Internal energy refers to microscopic motion and interactions. It excludes the bulk motion of the whole sample."]},{"id":"e02","type":"mcq","topic":"energy","prompt":"With Q positive into the system and W positive for work done by it, the first law is…","options":["ΔU = Q + W","ΔU = Q − W","ΔU = W − Q","ΔU = Q/W"],"correct":1,"answer":"ΔU = Q − W","explanation":"Heat entering increases internal energy; work leaving reduces it. Thus ΔU=Q−W.","difficulty":"Recall","steps":["Heat entering increases internal energy; work leaving reduces it. Thus ΔU=Q−W."]},{"id":"e03","type":"mcq","topic":"energy","prompt":"A gas absorbs 500 J of heat and does 180 J of work. Its internal-energy change is…","options":["+680 J","+320 J","−320 J","−680 J"],"correct":1,"answer":"+320 J","explanation":"ΔU=Q−W=500−180=320 J.","difficulty":"Calculation","steps":["ΔU=Q−W=500−180=320 J."]},{"id":"e04","type":"mcq","topic":"energy","prompt":"A gas loses 80 J of heat while 200 J of work is done on it. Its internal-energy change is…","options":["−280 J","−120 J","+120 J","+280 J"],"correct":2,"answer":"+120 J","explanation":"Q=−80 J and Wby=−200 J. Hence ΔU=−80−(−200)=120 J.","difficulty":"Challenge","steps":["Heat leaves, so Q = −80 J. Work is done on the gas, so Wby = −200 J.","ΔU = Q − Wby = −80 − (−200) = +120 J."]},{"id":"e05","type":"mcq","topic":"energy","prompt":"Which is a state function?","options":["Heat transferred","Work done","Internal energy","The path taken"],"correct":2,"answer":"Internal energy","explanation":"Internal energy depends on the thermodynamic state. Heat and work depend on the path between states.","difficulty":"Concept","steps":["Internal energy depends on the thermodynamic state. Heat and work depend on the path between states."]},{"id":"e06","type":"mcq","topic":"energy","prompt":"A system returns to its initial state in a complete cycle. If its net heat input is 250 J, its net work output is…","options":["0 J","125 J","250 J","500 J"],"correct":2,"answer":"250 J","explanation":"Over the full cycle ΔU=0. The first law gives Qnet=Wnet, so net work output is 250 J.","difficulty":"Calculation","steps":["For a complete cycle, final and initial internal energies are equal, so ΔU = 0.","0 = Qnet − Wnet, hence Wnet = 250 J."]},{"id":"e07","type":"mcq","topic":"energy","prompt":"For a fixed amount and composition of ideal gas, internal energy depends only on…","options":["Temperature","Volume","Pressure","Container shape"],"correct":0,"answer":"Temperature","explanation":"An ideal gas has no intermolecular potential-energy contribution. Its internal energy depends only on temperature for fixed amount/composition.","difficulty":"Concept","steps":["An ideal gas has no intermolecular potential-energy contribution. Its internal energy depends only on temperature for fixed amount/composition."]},{"id":"e08","type":"mcq","topic":"energy","prompt":"If work done on the system is denoted Won, the first law becomes…","options":["ΔU = Q − Won","ΔU = Q + Won","ΔU = Won − Q","ΔU = QWon"],"correct":1,"answer":"ΔU = Q + Won","explanation":"Won=−Wby, so ΔU=Q−Wby=Q+Won. The conventions are equivalent if used consistently.","difficulty":"Concept","steps":["Won=−Wby, so ΔU=Q−Wby=Q+Won. The conventions are equivalent if used consistently."]},{"id":"e09","type":"mcq","topic":"energy","prompt":"Between the same two states, path A has Q = 500 J and Wby = 200 J. If path B has Wby = 80 J, its heat input is…","options":["220 J","300 J","380 J","580 J"],"correct":2,"answer":"380 J","explanation":"Path A gives ΔU=300 J. The same endpoints require the same ΔU for path B, so QB=ΔU+WB=300+80=380 J.","difficulty":"Challenge","steps":["Path A: ΔU = 500 − 200 = 300 J.","Internal energy is a state function, so path B also has ΔU = 300 J.","QB = ΔU + WB = 300 + 80 = 380 J."]},{"id":"e10","type":"mcq","topic":"energy","prompt":"For an ideal monatomic gas with only translational energy, internal energy of n moles is…","options":["3kT/2 for the whole sample","3nRT/2","nRT/3","Independent of n"],"correct":1,"answer":"3nRT/2","explanation":"Each particle has mean translational energy 3kT/2. Multiplying by nNA gives 3nRT/2 for the whole sample.","difficulty":"Concept","steps":["Each particle has mean translational energy 3kT/2. Multiplying by nNA gives 3nRT/2 for the whole sample."]},{"id":"t01","type":"mcq","topic":"processes","prompt":"An isochoric process keeps which quantity constant?","options":["Pressure","Temperature","Volume","Heat input"],"correct":2,"answer":"Volume","explanation":"Isochoric means constant volume. The corresponding PV curve is vertical.","difficulty":"Recall","steps":["Isochoric means constant volume. The corresponding PV curve is vertical."]},{"id":"t02","type":"mcq","topic":"processes","prompt":"For a rigid closed system with only PV work, 300 J of heat is added. Its internal energy changes by…","options":["0 J","+150 J","+300 J","−300 J"],"correct":2,"answer":"+300 J","explanation":"The rigid boundary gives W=0. Therefore ΔU=Q=300 J.","difficulty":"Calculation","steps":["The rigid boundary gives W=0. Therefore ΔU=Q=300 J."]},{"id":"t03","type":"mcq","topic":"processes","prompt":"An isobaric process keeps which quantity constant?","options":["Pressure","Volume","Internal energy","Temperature"],"correct":0,"answer":"Pressure","explanation":"Isobaric means constant pressure. Volume and temperature may still change.","difficulty":"Recall","steps":["Isobaric means constant pressure. Volume and temperature may still change."]},{"id":"t04","type":"mcq","topic":"processes","prompt":"A fixed ideal-gas sample expands isothermally and does 450 J of work. Its heat input is…","options":["0 J","+450 J","−450 J","+900 J"],"correct":1,"answer":"+450 J","explanation":"Constant temperature for a fixed ideal gas gives ΔU=0. Thus Q=W=450 J.","difficulty":"Calculation","steps":["For a fixed ideal gas at constant temperature, ΔU = 0.","0 = Q − 450, so Q = +450 J. Heat must enter to maintain temperature."]},{"id":"t05","type":"mcq","topic":"processes","prompt":"The defining condition of an adiabatic process is…","options":["W = 0","ΔU = 0","Q = 0","ΔT = 0"],"correct":2,"answer":"Q = 0","explanation":"Adiabatic means no heat transfer. Temperature and internal energy can still change through work.","difficulty":"Recall","steps":["Adiabatic means no heat transfer. Temperature and internal energy can still change through work."]},{"id":"t06","type":"mcq","topic":"processes","prompt":"An ideal gas expands adiabatically and does positive work. Its temperature generally…","options":["Increases","Decreases","Must stay constant","Becomes zero"],"correct":1,"answer":"Decreases","explanation":"Q=0 and W>0 give ΔU=−W<0. For fixed ideal gas, decreasing internal energy means decreasing temperature.","difficulty":"Concept","steps":["Q=0 and W>0 give ΔU=−W<0. For fixed ideal gas, decreasing internal energy means decreasing temperature."]},{"id":"t07","type":"mcq","topic":"processes","prompt":"An insulated gas has 240 J of work done on it. Its internal-energy change is…","options":["−240 J","0 J","+120 J","+240 J"],"correct":3,"answer":"+240 J","explanation":"Q=0 and Wby=−240 J. Thus ΔU=0−(−240)=+240 J.","difficulty":"Calculation","steps":["Insulation gives Q = 0. Work done on the gas means Wby = −240 J.","ΔU = Q − Wby = 0 − (−240) = +240 J."]},{"id":"t08","type":"mcq","topic":"processes","prompt":"During isothermal compression of a fixed ideal gas, the gas…","options":["Absorbs heat equal to its work input","Rejects heat while ΔU stays zero","Has Q = 0 by definition","Always increases internal energy"],"correct":1,"answer":"Rejects heat while ΔU stays zero","explanation":"Isothermal ideal-gas ΔU=0. Compression has Wby<0, so Q=Wby<0: heat leaves the gas.","difficulty":"Concept","steps":["Isothermal ideal-gas ΔU=0. Compression has Wby<0, so Q=Wby<0: heat leaves the gas."]},{"id":"t09","type":"mcq","topic":"processes","prompt":"A gas absorbs 700 J while expanding by 2 L at constant pressure 100 kPa. Its internal-energy increase is…","options":["200 J","500 J","700 J","900 J"],"correct":1,"answer":"500 J","explanation":"W=PΔV=100×2=200 J. ΔU=700−200=500 J.","difficulty":"Challenge","steps":["Wby = PΔV = 100 kPa × 2 L = 200 J.","ΔU = Q − Wby = 700 − 200 = 500 J."]},{"id":"t10","type":"mcq","topic":"processes","prompt":"Which statement is correct?","options":["Every adiabatic process is isothermal","Every isothermal process has Q = 0","An adiabatic process can change temperature","Constant volume requires constant pressure"],"correct":2,"answer":"An adiabatic process can change temperature","explanation":"Adiabatic fixes heat transfer at zero, not temperature. Work can change internal energy and temperature.","difficulty":"Concept","steps":["Adiabatic fixes heat transfer at zero, not temperature. Work can change internal energy and temperature."]},{"id":"c01","type":"mcq","topic":"capacity","prompt":"The SI unit of the heat capacity of a whole body is…","options":["J/K","J kg⁻¹ K⁻¹","J mol⁻¹ K⁻¹","K/J"],"correct":0,"answer":"J/K","explanation":"Whole-body heat capacity is energy per temperature rise, Cbody=Q/ΔT, measured in J/K.","difficulty":"Recall","steps":["Whole-body heat capacity is energy per temperature rise, Cbody=Q/ΔT, measured in J/K."]},{"id":"c02","type":"mcq","topic":"capacity","prompt":"The SI unit of mass-specific heat capacity is…","options":["J/K","J kg⁻¹ K⁻¹","J mol⁻¹ K⁻¹","kg K/J"],"correct":1,"answer":"J kg⁻¹ K⁻¹","explanation":"Specific heat capacity c=Q/(mΔT) is measured in joules per kilogram per kelvin.","difficulty":"Recall","steps":["Specific heat capacity c=Q/(mΔT) is measured in joules per kilogram per kelvin."]},{"id":"c03","type":"mcq","topic":"capacity","prompt":"A 0.20 kg sample has c = 4200 J kg⁻¹ K⁻¹ and warms by 20 K without a phase change. Required heat is…","options":["840 J","4200 J","16800 J","42000 J"],"correct":2,"answer":"16800 J","explanation":"Q=mcΔT=0.20×4200×20=16800 J.","difficulty":"Calculation","steps":["Use Q = mcΔT with compatible SI units.","Q = 0.20 × 4200 × 20 = 16800 J = 16.8 kJ."]},{"id":"c04","type":"mcq","topic":"capacity","prompt":"Heating from 20 °C to 45 °C gives a temperature change of…","options":["25 K","65 K","298 K","318 K"],"correct":0,"answer":"25 K","explanation":"ΔT=45−20=25 °C, and a Celsius temperature difference has the same numerical value in kelvin. Do not add 273 to a difference.","difficulty":"Calculation","steps":["ΔT=45−20=25 °C, and a Celsius temperature difference has the same numerical value in kelvin. Do not add 273 to a difference."]},{"id":"c05","type":"mcq","topic":"capacity","prompt":"A 0.50 kg body with c = 400 J kg⁻¹ K⁻¹ cools from 80 °C to 30 °C. Heat transferred into the body is…","options":["+10000 J","−10000 J","+20000 J","−20000 J"],"correct":1,"answer":"−10000 J","explanation":"ΔT=30−80=−50 K. Q=0.50×400×(−50)=−10000 J. Negative Q denotes heat loss.","difficulty":"Calculation","steps":["ΔT = 30 − 80 = −50 K.","Qinto = mcΔT = 0.50 × 400 × (−50) = −10000 J. Heat lost has magnitude 10000 J."]},{"id":"c06","type":"mcq","topic":"capacity","prompt":"If the mass of a sample doubles while its material and c stay the same, its whole-body heat capacity…","options":["Halves","Doubles","Stays the same","Becomes zero"],"correct":1,"answer":"Doubles","explanation":"Cbody=mc. Doubling mass doubles total heat capacity while the material-specific c remains the same.","difficulty":"Concept","steps":["Cbody=mc. Doubling mass doubles total heat capacity while the material-specific c remains the same."]},{"id":"c07","type":"mcq","topic":"capacity","prompt":"A body absorbs 600 J and its temperature rises by 3 K under specified conditions. Its heat capacity is…","options":["1800 J/K","600 J/K","200 J/K","2 J/K"],"correct":2,"answer":"200 J/K","explanation":"Cbody=Q/ΔT=600/3=200 J/K.","difficulty":"Calculation","steps":["Cbody=Q/ΔT=600/3=200 J/K."]},{"id":"c08","type":"mcq","topic":"capacity","prompt":"100 g of water at 80 °C is mixed with 200 g at 20 °C. Ignore container heat capacity, heat loss and phase change. Final temperature is…","options":["30 °C","40 °C","50 °C","60 °C"],"correct":1,"answer":"40 °C","explanation":"Same c cancels: 100(80−Tf)=200(Tf−20). Solving gives 12000=300Tf, so Tf=40 °C.","difficulty":"Challenge","steps":["Heat lost = heat gained: 100c(80 − Tf) = 200c(Tf − 20).","Cancel c and expand: 8000 − 100Tf = 200Tf − 4000.","12000 = 300Tf, so Tf = 40 °C."]},{"id":"c09","type":"mcq","topic":"capacity","prompt":"Which condition makes Q = mcΔT alone unsuitable?","options":["Mass is given in kilograms","Temperature difference is in kelvin","A phase change occurs at constant temperature","The heat capacity is approximately constant"],"correct":2,"answer":"A phase change occurs at constant temperature","explanation":"During a phase change, heat can be transferred without a temperature change. A latent-heat term is needed; mcΔT alone does not account for it.","difficulty":"Concept","steps":["During a phase change, heat can be transferred without a temperature change. A latent-heat term is needed; mcΔT alone does not account for it."]},{"id":"c10","type":"mcq","topic":"capacity","prompt":"For the same mass and heat input, a material with larger specific heat capacity has…","options":["A larger temperature rise","A smaller temperature rise","No possible temperature change","Necessarily the same temperature rise"],"correct":1,"answer":"A smaller temperature rise","explanation":"ΔT=Q/(mc). With Q and m fixed, increasing c reduces the temperature rise.","difficulty":"Concept","steps":["ΔT=Q/(mc). With Q and m fixed, increasing c reduces the temperature rise."]},{"id":"m01","type":"mcq","topic":"molar","prompt":"The SI unit of molar heat capacity is…","options":["J/K","J kg⁻¹ K⁻¹","J mol⁻¹ K⁻¹","mol K/J"],"correct":2,"answer":"J mol⁻¹ K⁻¹","explanation":"Molar capacity is energy per mole per temperature rise, Cm=Q/(nΔT).","difficulty":"Recall","steps":["Molar capacity is energy per mole per temperature rise, Cm=Q/(nΔT)."]},{"id":"m02","type":"mcq","topic":"molar","prompt":"Two moles absorb 1500 J while warming by 25 K in a specified process. The molar heat capacity is…","options":["15 J mol⁻¹ K⁻¹","30 J mol⁻¹ K⁻¹","60 J mol⁻¹ K⁻¹","750 J mol⁻¹ K⁻¹"],"correct":1,"answer":"30 J mol⁻¹ K⁻¹","explanation":"Cm=Q/(nΔT)=1500/(2×25)=30 J mol⁻¹ K⁻¹. The total sample capacity is 60 J/K.","difficulty":"Calculation","steps":["Cm=Q/(nΔT)=1500/(2×25)=30 J mol⁻¹ K⁻¹. The total sample capacity is 60 J/K."]},{"id":"m03","type":"mcq","topic":"molar","prompt":"For an ideal gas, the difference between molar Cp and molar Cv is…","options":["0","R","nR for every molar value","Cp + Cv"],"correct":1,"answer":"R","explanation":"Mayer’s relation for molar capacities is Cp−Cv=R. The difference between total n-mole capacities is nR.","difficulty":"Concept","steps":["Mayer’s relation for molar capacities is Cp−Cv=R. The difference between total n-mole capacities is nR."]},{"id":"m04","type":"mcq","topic":"molar","prompt":"An ideal gas has Cv = 20 J mol⁻¹ K⁻¹. Use R = 8.31 J mol⁻¹ K⁻¹. Its Cp is…","options":["11.69 J mol⁻¹ K⁻¹","20 J mol⁻¹ K⁻¹","28.31 J mol⁻¹ K⁻¹","166.2 J mol⁻¹ K⁻¹"],"correct":2,"answer":"28.31 J mol⁻¹ K⁻¹","explanation":"Cp=Cv+R=20+8.31=28.31 J mol⁻¹ K⁻¹.","difficulty":"Calculation","steps":["For ideal-gas molar capacities, Cp − Cv = R.","Cp = 20 + 8.31 = 28.31 J mol⁻¹ K⁻¹."]},{"id":"m05","type":"mcq","topic":"molar","prompt":"For a fixed ideal gas heated with only PV work, Cp exceeds Cv because at constant pressure…","options":["Temperature cannot change","Some heat supplies expansion work","No heat enters the gas","Internal energy depends on pressure alone"],"correct":1,"answer":"Some heat supplies expansion work","explanation":"At constant volume, heat increases U without boundary work. At constant pressure, expansion also requires energy, so more heat is needed for the same temperature rise.","difficulty":"Concept","steps":["At constant volume, heat increases U without boundary work. At constant pressure, expansion also requires energy, so more heat is needed for the same temperature rise."]},{"id":"m06","type":"mcq","topic":"molar","prompt":"Two moles of ideal gas with Cv = 12.5 J mol⁻¹ K⁻¹ warm by 20 K. Their internal-energy change is…","options":["125 J","250 J","500 J","1000 J"],"correct":2,"answer":"500 J","explanation":"ΔU=nCvΔT=2×12.5×20=500 J. For fixed ideal gas this ΔU applies regardless of the path.","difficulty":"Calculation","steps":["For a fixed ideal-gas sample, ΔU = nCvΔT.","ΔU = 2 × 12.5 × 20 = 500 J."]},{"id":"m07","type":"mcq","topic":"molar","prompt":"If molar mass M is in kg/mol and c is in J kg⁻¹ K⁻¹, molar heat capacity is…","options":["c/M","Mc","M/c","c + M"],"correct":1,"answer":"Mc","explanation":"For the same conditions, the heat capacity of one mole is its mass M times the mass-specific heat capacity c. Thus Cm=Mc.","difficulty":"Concept","steps":["For the same conditions, the heat capacity of one mole is its mass M times the mass-specific heat capacity c. Thus Cm=Mc."]},{"id":"m08","type":"mcq","topic":"molar","prompt":"An ideal gas has Cp = 29.1 and Cv = 20.8 J mol⁻¹ K⁻¹. Its heat-capacity ratio γ is approximately…","options":["0.71","1.00","1.40","2.40"],"correct":2,"answer":"1.40","explanation":"γ=Cp/Cv=29.1/20.8≈1.40. Both capacities must be expressed for the same amount and in compatible units.","difficulty":"Calculation","steps":["γ=Cp/Cv=29.1/20.8≈1.40. Both capacities must be expressed for the same amount and in compatible units."]},{"id":"m09","type":"mcq","topic":"molar","prompt":"One mole of ideal gas with Cv = 20 J mol⁻¹ K⁻¹ warms by 10 K at constant pressure. Use R = 8.31 J mol⁻¹ K⁻¹. Heat absorbed is…","options":["83.1 J","200 J","283.1 J","831 J"],"correct":2,"answer":"283.1 J","explanation":"ΔU=nCvΔT=200 J. W=nRΔT=83.1 J. Q=ΔU+W=283.1 J.","difficulty":"Challenge","steps":["ΔU = 1 × 20 × 10 = 200 J.","At constant pressure, W = nRΔT = 1 × 8.31 × 10 = 83.1 J.","Q = ΔU + W = 200 + 83.1 = 283.1 J."]},{"id":"m10","type":"mcq","topic":"molar","prompt":"If γ = 1.40 for an ideal gas, its molar Cv in terms of R is…","options":["0.4R","1.4R","2.5R","3.5R"],"correct":2,"answer":"2.5R","explanation":"Cp=γCv and Cp−Cv=R imply (γ−1)Cv=R. Thus Cv=R/0.40=2.5R.","difficulty":"Challenge","steps":["Cp = γCv and Cp − Cv = R.","(γ − 1)Cv = R, so Cv = R/(1.40 − 1) = R/0.40 = 2.5R."]}],"cards":[{"id":"hc1","type":"card","topic":"heat","prompt":"Distinguish heat from temperature.","answer":"Heat is energy transfer; temperature describes a thermal state.","explanation":"Heat is measured in joules and crosses a boundary due to a temperature difference. Temperature is measured in kelvin. A hot object stores internal energy, not heat as a state property.","difficulty":"Recall"},{"id":"hc2","type":"card","topic":"heat","prompt":"Identify the system, surroundings and boundary for gas in a piston cylinder.","answer":"System: gas. Surroundings: piston and outside environment. Boundary: surface enclosing the gas.","explanation":"This choice lets us track heat entering the gas and work leaving it as the piston moves. The boundary moves during expansion.","difficulty":"Recall"},{"id":"hc3","type":"card","topic":"heat","prompt":"Compare open, closed and isolated systems.","answer":"Open exchanges matter and energy; closed exchanges energy only; isolated exchanges neither.","explanation":"An uncovered drink is open. A sealed piston cylinder can be closed. A perfectly insulated, sealed, rigid container approximates an isolated system.","difficulty":"Recall"},{"id":"hc4","type":"card","topic":"heat","prompt":"Does an insulated boundary guarantee an isolated system?","answer":"No. Work may still cross the boundary.","explanation":"An insulated gas can do work by moving a piston. It is adiabatic because Q=0, but not isolated if it transfers energy as work.","difficulty":"Recall"},{"id":"hc5","type":"card","topic":"heat","prompt":"Fill in the blank: the SI unit of heat is the ____.","answer":"Joule","explanation":"Heat is an energy transfer, so it has the same SI unit as work and internal energy.","difficulty":"Recall"},{"id":"hc6","type":"card","topic":"heat","prompt":"Explain how compression can increase temperature without heat entering a gas.","answer":"Work done on the gas can increase its internal energy.","explanation":"For adiabatic compression, Q=0 and work done by the gas is negative. Hence ΔU=−W is positive; a fixed ideal-gas sample warms.","difficulty":"Recall"},{"id":"wc1","type":"card","topic":"work","prompt":"Derive W = Pext ΔV for a piston at constant external pressure.","answer":"W=Fs=Pext As=Pext ΔV.","explanation":"Pressure times piston area gives the opposing force. Area times outward displacement gives the volume increase. The result is positive for expansion under the by-gas convention.","difficulty":"Derivation"},{"id":"wc2","type":"card","topic":"work","prompt":"What does area under a quasistatic PV curve represent?","answer":"The signed work done by the gas.","explanation":"W=∫P dV. Moving right gives positive expansion work; moving left gives negative compression work. A vertical constant-volume segment has zero area and zero boundary work.","difficulty":"Recall"},{"id":"wc3","type":"card","topic":"work","prompt":"Find the work for expansion by 4 L against 150 kPa constant external pressure.","answer":"600 J","explanation":"Use 1 kPa L=1 J. W=150×4=600 J. This is work by the gas; work on it is −600 J.","difficulty":"Calculation"},{"id":"wc4","type":"card","topic":"work","prompt":"Why can two paths between the same states have different work?","answer":"They can enclose different areas under their PV curves.","explanation":"Work depends on how the volume changes at each pressure, not just the endpoint values. It is a path-dependent energy transfer.","difficulty":"Recall"},{"id":"wc5","type":"card","topic":"work","prompt":"Fill in the blank: 1 L = ____ m³.","answer":"0.001 m³","explanation":"A litre is 10⁻³ cubic metres. Convert pressure and volume consistently before evaluating PΔV.","difficulty":"Recall"},{"id":"wc6","type":"card","topic":"work","prompt":"Why is work zero for free expansion into vacuum?","answer":"There is no external pressure opposing the expansion.","explanation":"The gas may increase its volume, but W=∫Pext dV=0 when Pext=0. Volume increase alone does not guarantee nonzero external work.","difficulty":"Recall"},{"id":"ec1","type":"card","topic":"energy","prompt":"State the first law and define the signs used on this page.","answer":"ΔU=Q−W, with Q positive into the gas and W positive for work done by it.","explanation":"This is energy conservation for the chosen closed system when bulk kinetic/potential changes are negligible. Work on the gas is negative Wby and raises its internal energy.","difficulty":"Recall"},{"id":"ec2","type":"card","topic":"energy","prompt":"Calculate ΔU when a gas absorbs 900 J and does 250 J of work.","answer":"+650 J","explanation":"ΔU=Q−W=900−250=650 J. The gas retains the portion of the heat input that is not transferred out as work.","difficulty":"Calculation"},{"id":"ec3","type":"card","topic":"energy","prompt":"A gas loses 100 J of heat and receives 350 J of work. Find ΔU.","answer":"+250 J","explanation":"Q=−100 J and Wby=−350 J. ΔU=−100−(−350)=250 J. Equivalently use Q+Won.","difficulty":"Calculation"},{"id":"ec4","type":"card","topic":"energy","prompt":"Why is ΔU the same for different paths between the same states?","answer":"Internal energy is a state function.","explanation":"Although Q and W can vary with the path, Q−W is fixed by Ufinal−Uinitial. For a complete cycle, ΔU=0.","difficulty":"Recall"},{"id":"ec5","type":"card","topic":"energy","prompt":"Fill in the blank: for a complete cycle, net heat input equals net ____ output.","answer":"Work","explanation":"Returning to the initial state gives ΔU=0. Hence Qnet−Wnet=0 and Qnet=Wnet.","difficulty":"Recall"},{"id":"ec6","type":"card","topic":"energy","prompt":"Compare 3kT/2 and 3nRT/2 for an ideal monatomic gas.","answer":"The first is mean energy per particle; the second is total energy of n moles.","explanation":"Since the particle number is nNA and R=NAk, multiplying the per-particle value by particle count gives the whole-sample expression.","difficulty":"Recall"},{"id":"tc1","type":"card","topic":"processes","prompt":"Compare isochoric, isobaric, isothermal and adiabatic processes.","answer":"Constant V, constant P, constant T, and zero heat transfer, respectively.","explanation":"For only PV work: isochoric gives W=0; isobaric gives W=PΔV; fixed ideal-gas isothermal gives ΔU=0; adiabatic gives Q=0 and ΔU=−W.","difficulty":"Recall"},{"id":"tc2","type":"card","topic":"processes","prompt":"Why does heating a gas at constant volume give Q=ΔU in the simple piston model?","answer":"There is no PV work because ΔV=0.","explanation":"With other work excluded, the first law is ΔU=Q−0. This does not claim that every rigid system is unable to receive electrical or stirring work.","difficulty":"Recall"},{"id":"tc3","type":"card","topic":"processes","prompt":"How can an ideal gas expand at constant temperature while doing work?","answer":"It absorbs heat equal to the work output.","explanation":"Its internal energy remains unchanged at fixed T. Heat from a reservoir replaces the energy leaving as work, so Q=W.","difficulty":"Recall"},{"id":"tc4","type":"card","topic":"processes","prompt":"Explain why an ideal gas warms during adiabatic compression.","answer":"Work on the gas increases its internal energy while Q=0.","explanation":"Wby is negative, so ΔU=−Wby is positive. For a fixed ideal-gas sample, positive ΔU means higher temperature.","difficulty":"Recall"},{"id":"tc5","type":"card","topic":"processes","prompt":"Fill in the blank: a process with no heat transfer is ____.","answer":"Adiabatic","explanation":"Q=0 defines an adiabatic process. It can be approximated by insulation or a fast change compared with the heat-transfer timescale.","difficulty":"Recall"},{"id":"tc6","type":"card","topic":"processes","prompt":"State the assumptions needed for PV^γ = constant.","answer":"A reversible adiabatic ideal-gas process with constant γ.","explanation":"The general adiabatic energy result Q=0, ΔU=−W does not need reversibility. Do not apply the PV^γ relation to every free or irreversible expansion.","difficulty":"Recall"},{"id":"cc1","type":"card","topic":"capacity","prompt":"Distinguish heat capacity from specific heat capacity.","answer":"Heat capacity applies to a whole sample; specific heat capacity is per unit mass.","explanation":"Cbody has unit J/K and equals mc. The mass-specific c has unit J kg⁻¹ K⁻¹ and does not depend on sample size under the same physical conditions.","difficulty":"Recall"},{"id":"cc2","type":"card","topic":"capacity","prompt":"Find the heat required to warm 0.30 kg of material by 20 K if c=500 J kg⁻¹ K⁻¹.","answer":"3000 J","explanation":"Q=mcΔT=0.30×500×20=3000 J, assuming no phase change and an appropriate constant c.","difficulty":"Calculation"},{"id":"cc3","type":"card","topic":"capacity","prompt":"Why is a rise of 15 °C also a rise of 15 K?","answer":"Kelvin and Celsius have the same size temperature interval.","explanation":"Their zero points differ, but the offset cancels when subtracting initial from final temperature. Never add 273 to ΔT.","difficulty":"Recall"},{"id":"cc4","type":"card","topic":"capacity","prompt":"State the energy balance used in simple calorimetry.","answer":"Heat lost by hot material equals heat gained by cold material.","explanation":"This assumes the combined system loses negligible heat externally, no phase change occurs, and any neglected calorimeter heat capacity is small. Use mc times each temperature change.","difficulty":"Recall"},{"id":"cc5","type":"card","topic":"capacity","prompt":"Fill in the blank: Cbody = m ____.","answer":"c, the mass-specific heat capacity","explanation":"Since Q=mcΔT and Cbody=Q/ΔT, the total heat capacity is mc. Units are kg×J kg⁻¹ K⁻¹=J/K.","difficulty":"Recall"},{"id":"cc6","type":"card","topic":"capacity","prompt":"Why can a body absorb heat without increasing temperature?","answer":"A phase change can use the energy to change microscopic interactions.","explanation":"During melting or boiling at fixed pressure, added energy can increase internal potential energy rather than temperature. A latent-heat term is then needed.","difficulty":"Recall"},{"id":"mc1","type":"card","topic":"molar","prompt":"Define molar heat capacity and its unit.","answer":"Energy per mole per kelvin: Cm=Q/(nΔT), in J mol⁻¹ K⁻¹.","explanation":"The process must be specified because a gas can absorb different amounts of heat for the same temperature rise at constant pressure and constant volume.","difficulty":"Recall"},{"id":"mc2","type":"card","topic":"molar","prompt":"Derive Cp−Cv=R for one mole of ideal gas.","answer":"Use Q=ΔU+W at constant pressure to obtain CpΔT=CvΔT+RΔT.","explanation":"For one mole, Q=CpΔT, ΔU=CvΔT, and W=PΔV=RΔT. Cancel a nonzero ΔT to obtain Cp−Cv=R. These are molar capacities.","difficulty":"Derivation"},{"id":"mc3","type":"card","topic":"molar","prompt":"Why does constant-pressure heating require more heat than constant-volume heating for the same ideal-gas temperature rise?","answer":"At constant pressure, heat must also supply expansion work.","explanation":"The internal-energy rise nCvΔT is the same. At constant volume W=0, while at constant pressure W=nRΔT, so Qp exceeds Qv by nRΔT.","difficulty":"Recall"},{"id":"mc4","type":"card","topic":"molar","prompt":"Find ΔU for 3 mol of ideal gas with Cv=15 J mol⁻¹ K⁻¹ and ΔT=4 K.","answer":"180 J","explanation":"ΔU=nCvΔT=3×15×4=180 J. The gas amount and heat capacity must use compatible mole units.","difficulty":"Calculation"},{"id":"mc5","type":"card","topic":"molar","prompt":"Fill in the blank: γ = Cp divided by ____.","answer":"Cv","explanation":"γ is the ratio of constant-pressure to constant-volume heat capacities. For a stable ideal gas with positive Cv, Cp=Cv+R makes γ greater than 1.","difficulty":"Recall"},{"id":"mc6","type":"card","topic":"molar","prompt":"Distinguish molar and total heat-capacity differences for n moles of ideal gas.","answer":"Molar: Cp−Cv=R. Total sample: Ctotal,p−Ctotal,v=nR.","explanation":"Multiplying molar capacities by n gives whole-sample capacities. Confusing these quantities introduces an incorrect extra factor of n.","difficulty":"Recall"}],"topics":[{"id":"heat","name":"Heat & thermal systems","pages":"17–21"},{"id":"work","name":"Work done by a gas","pages":"21–23, 27–28"},{"id":"energy","name":"Internal energy & first law","pages":"19, 23–24, 32"},{"id":"processes","name":"Thermodynamic processes","pages":"24–28, 33–34"},{"id":"capacity","name":"Heat capacity & calorimetry","pages":"29–31, 34"},{"id":"molar","name":"Molar heat capacities","pages":"29–31"}]}};
